function rampartSimulate(createStrategy, seed, maxTicks, trace) {
  'use strict';
  // ---- static rule tables (section 2) ----
  var TYPE_NAMES = ['bolt', 'cannon', 'frost', 'lance', 'flak'];
  var T_COST = [50, 90, 70, 120, 80];
  var T_DMG = [26, 60, 10, 180, 40];
  var T_PER = [8, 24, 12, 36, 10];
  var T_RNG = [300, 260, 240, 360, 320];
  var T_SPL = [0, 90, 0, 0, 70];
  var T_SLOW = [0, 0, 30, 0, 0];
  var T_PIERCE = [0, 0, 0, 1, 0];
  var T_GROUND = [1, 1, 1, 1, 0];
  var T_AIR = [1, 0, 1, 0, 1];
  var E_NAMES = ['grunt', 'runner', 'wisp', 'brute', 'splitter', 'mender', 'splitling'];
  var E_HP = [60, 40, 50, 150, 90, 70, 0];
  var E_SPD = [10, 20, 12, 6, 8, 8, 12];
  var E_BOUNTY = [4, 4, 6, 9, 6, 7, 1];
  var E_LEAK = [1, 1, 2, 3, 2, 2, 1];
  var E_AIR = [0, 0, 1, 0, 0, 0, 0];
  var E_FIRST = [1, 2, 3, 4, 6, 8, 0];
  var E_WEIGHT = [10, 4, 3, 3, 2, 1, 0];
  var SLOT_TILES = [[3, 3], [5, 5], [7, 4], [7, 8], [9, 9], [10, 5], [11, 8], [13, 8], [14, 5], [15, 2], [16, 7], [17, 4], [19, 8], [20, 10], [22, 9], [3, 7]];
  var GROUND_PTS = [[0, 2], [6, 2], [6, 10], [12, 10], [12, 3], [18, 3], [18, 11], [23, 11]];
  var AIR_PTS = [[0, 6], [21, 6], [21, 11], [23, 11]];

  function buildRoute(pts) {
    var xs = [], ys = [];
    for (var i = 0; i < pts.length - 1; i++) {
      var ax = pts[i][0] * 100 + 50, ay = pts[i][1] * 100 + 50;
      var bx = pts[i + 1][0] * 100 + 50, by = pts[i + 1][1] * 100 + 50;
      var n = Math.abs(bx - ax) + Math.abs(by - ay);
      var dx = bx > ax ? 1 : bx < ax ? -1 : 0, dy = by > ay ? 1 : by < ay ? -1 : 0;
      for (var k = 0; k < n; k++) { xs.push(ax + dx * k); ys.push(ay + dy * k); }
    }
    var last = pts[pts.length - 1];
    xs.push(last[0] * 100 + 50); ys.push(last[1] * 100 + 50);
    return { xs: xs, ys: ys, len: xs.length - 1 };
  }
  var ROUTES = [buildRoute(GROUND_PTS), buildRoute(AIR_PTS)];

  // tier tables
  var DMG_T = [], RNG_T = [];
  for (var ty = 0; ty < 5; ty++) {
    var d1 = T_DMG[ty], d2 = Math.floor(d1 * 16 / 10), d3 = Math.floor(d2 * 16 / 10);
    DMG_T.push([0, d1, d2, d3]);
    RNG_T.push([0, T_RNG[ty], T_RNG[ty] + 30, T_RNG[ty] + 60]);
  }

  // hp multiplier m(w)
  var MULT = [0, 1000];
  function mult(w) { while (MULT.length <= w) MULT.push(Math.floor(MULT[MULT.length - 1] * 108 / 100)); return MULT[w]; }

  // ---- composition generator ----
  function mulberry32(a) {
    return function () {
      a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return (t ^ (t >>> 14)) >>> 0;
    };
  }
  var rng = mulberry32(seed);
  var waves = [null];
  function ensureWave(w) {
    while (waves.length <= w) {
      var wn = waves.length, avail = [], sum = 0;
      for (var t = 0; t < 6; t++) if (E_FIRST[t] <= wn) { avail.push(t); sum += E_WEIGHT[t]; }
      var n = 4 + Math.floor(3 * wn / 5), comp = [];
      for (var i = 0; i < n; i++) {
        var r = rng() % sum;
        for (var j = 0; j < avail.length; j++) {
          if (r < E_WEIGHT[avail[j]]) { comp.push(avail[j]); break; }
          r -= E_WEIGHT[avail[j]];
        }
      }
      waves.push(comp);
    }
  }

  // ---- game state ----
  var baseHp = 10, gold = 250, nextId = 1;
  var enemies = [];            // living enemies, ascending id
  var turrets = new Array(16); // null or {type,tier,spent,cd}
  for (var s0 = 0; s0 < 16; s0++) turrets[s0] = null;
  var spawnQueue = {};         // tick -> [ [type, wave], ... ] in (wave, index) order
  var log = [];
  var strat = createStrategy();
  var fallTick = -1, curWave = 0;

  function armorOf(e) { return e.type === 0 ? Math.floor(e.wave / 4) : e.type === 3 ? 6 + e.wave : 0; }
  function view(e) {
    var r = ROUTES[E_AIR[e.type]];
    return {
      id: e.id, type: E_NAMES[e.type], hp: e.hp, maxHp: e.maxHp,
      x: r.xs[e.progress], y: r.ys[e.progress], air: E_AIR[e.type], armor: armorOf(e),
      speed: e.slow > 0 ? Math.floor(E_SPD[e.type] * 60 / 100) : E_SPD[e.type],
      slowed: e.slow > 0 ? 1 : 0, remaining: r.len - e.progress
    };
  }
  function makeEnemy(type, wave, hp) {
    var e = { id: nextId++, type: type, wave: wave, hp: hp, maxHp: hp, progress: 0, age: 0, slow: 0 };
    return e;
  }

  if (trace) {
    trace.frames = []; trace.shots = []; trace.kills = []; trace.leaks = []; trace.heals = [];
    trace.waves = []; trace.routes = ROUTES;
  }

  function applyActions(acts, tick) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== 'object') continue;
      var slot = a.slot;
      if (typeof slot !== 'number' || slot !== Math.floor(slot) || slot < 0 || slot > 15) continue;
      if (a.op === 'build') {
        var ti = TYPE_NAMES.indexOf(a.type);
        if (ti < 0 || turrets[slot] || gold < T_COST[ti]) continue;
        gold -= T_COST[ti];
        turrets[slot] = { type: ti, tier: 1, spent: T_COST[ti], cd: 0 };
        log.push([tick, 'B', slot, ti]);
      } else if (a.op === 'upgrade') {
        var t = turrets[slot];
        if (!t || t.tier >= 3) continue;
        var cost = t.tier === 1 ? T_COST[t.type] : 2 * T_COST[t.type];
        if (gold < cost) continue;
        gold -= cost; t.spent += cost; t.tier++;
        log.push([tick, 'U', slot, t.tier]);
      } else if (a.op === 'sell') {
        var t2 = turrets[slot];
        if (!t2) continue;
        gold += Math.floor(t2.spent * 70 / 100);
        turrets[slot] = null;
        log.push([tick, 'S', slot, 0]);
      }
    }
  }

  for (var tick = 0; tick < maxTicks; tick++) {
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      var w = (tick - 20) / 40 + 1;
      curWave = w;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * w;
      ensureWave(w + 1);
      var state = {
        tick: tick, wave: w, gold: gold, baseHp: baseHp,
        slots: [], enemies: [], nextWave: []
      };
      for (var si = 0; si < 16; si++) {
        var tt = turrets[si];
        state.slots.push({
          slot: si, x: SLOT_TILES[si][0] * 100 + 50, y: SLOT_TILES[si][1] * 100 + 50,
          turret: tt ? { type: TYPE_NAMES[tt.type], tier: tt.tier, spent: tt.spent } : null
        });
      }
      for (var ei = 0; ei < enemies.length; ei++) state.enemies.push(view(enemies[ei]));
      for (var ni = 0; ni < waves[w + 1].length; ni++) state.nextWave.push(E_NAMES[waves[w + 1][ni]]);
      var acts = strat.plan(state);
      applyActions(acts, tick);
      var comp = waves[w];
      for (var ci = 0; ci < comp.length; ci++) {
        var st = tick + 4 * ci;
        (spawnQueue[st] || (spawnQueue[st] = [])).push([comp[ci], w]);
      }
      if (trace) trace.waves.push({ wave: w, tick: tick, comp: comp.slice(), next: waves[w + 1].slice() });
    }
    // 2. spawn
    var due = spawnQueue[tick];
    if (due) {
      for (var di = 0; di < due.length; di++) {
        var ty2 = due[di][0], wv = due[di][1];
        var hp = Math.floor(E_HP[ty2] * mult(wv) / 1000);
        enemies.push(makeEnemy(ty2, wv, hp));
      }
      delete spawnQueue[tick];
    }
    // 3. move
    var fell = false;
    var keep = null;
    for (var mi = 0; mi < enemies.length; mi++) {
      var e = enemies[mi];
      var rt = ROUTES[E_AIR[e.type]];
      e.progress += e.slow > 0 ? Math.floor(E_SPD[e.type] * 60 / 100) : E_SPD[e.type];
      if (e.progress >= rt.len) {
        baseHp -= E_LEAK[e.type];
        log.push([tick, 'L', e.id, baseHp]);
        if (trace) trace.leaks.push([tick, e.id, e.type, baseHp]);
        e.hp = -1000000; // mark removed
        if (baseHp <= 0) { fell = true; break; }
      }
    }
    if (fell) {
      fallTick = tick;
      log.push([tick, 'F', curWave, 0]);
      if (trace) trace.frames.push(null);
      break;
    }
    // drop leaked enemies
    {
      var any = false;
      for (var li = 0; li < enemies.length; li++) if (enemies[li].hp === -1000000) { any = true; break; }
      if (any) enemies = enemies.filter(function (q) { return q.hp !== -1000000; });
    }
    // 4. age & heal
    for (var ai = 0; ai < enemies.length; ai++) {
      var ea = enemies[ai];
      ea.age++;
      if (ea.type === 5 && ea.age % 20 === 0) {
        var mr = ROUTES[0], mx = mr.xs[ea.progress], my = mr.ys[ea.progress];
        for (var hi = 0; hi < enemies.length; hi++) {
          var eh = enemies[hi];
          var hr = ROUTES[E_AIR[eh.type]];
          var hdx = hr.xs[eh.progress] - mx, hdy = hr.ys[eh.progress] - my;
          if (hdx * hdx + hdy * hdy <= 150 * 150) {
            var heal = Math.floor(eh.maxHp * 8 / 100);
            eh.hp = Math.min(eh.maxHp, eh.hp + heal);
          }
        }
        if (trace) trace.heals.push([tick, mx, my]);
      }
    }
    // 5. turrets fire
    for (var ts = 0; ts < 16; ts++) {
      var tu = turrets[ts];
      if (!tu) continue;
      if (tu.cd > 0) tu.cd--;
      if (tu.cd > 0) continue;
      var tx = SLOT_TILES[ts][0] * 100 + 50, ty3 = SLOT_TILES[ts][1] * 100 + 50;
      var rng2 = RNG_T[tu.type][tu.tier]; rng2 *= rng2;
      var cands = [];
      for (var ce = 0; ce < enemies.length; ce++) {
        var c = enemies[ce];
        var air = E_AIR[c.type];
        if (air ? !T_AIR[tu.type] : !T_GROUND[tu.type]) continue;
        var cr = ROUTES[air];
        var cdx = cr.xs[c.progress] - tx, cdy = cr.ys[c.progress] - ty3;
        if (cdx * cdx + cdy * cdy <= rng2) cands.push(c);
      }
      if (cands.length === 0) continue;
      var tgt = null;
      if (typeof strat.target === 'function') {
        var tv = { slot: ts, type: TYPE_NAMES[tu.type], tier: tu.tier, x: tx, y: ty3, range: RNG_T[tu.type][tu.tier] };
        var cv = [];
        for (var vi = 0; vi < cands.length; vi++) cv.push(view(cands[vi]));
        var rid = strat.target(tv, cv);
        for (var qi = 0; qi < cands.length; qi++) if (cands[qi].id === rid) { tgt = cands[qi]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        var bestRem = ROUTES[E_AIR[tgt.type]].len - tgt.progress;
        for (var bi = 1; bi < cands.length; bi++) {
          var rem = ROUTES[E_AIR[cands[bi].type]].len - cands[bi].progress;
          if (rem < bestRem) { bestRem = rem; tgt = cands[bi]; }
        }
      }
      var tgtRoute = ROUTES[E_AIR[tgt.type]];
      var px = tgtRoute.xs[tgt.progress], py = tgtRoute.ys[tgt.progress];
      var base = DMG_T[tu.type][tu.tier];
      var pierce = T_PIERCE[tu.type], slowv = T_SLOW[tu.type], spl = T_SPL[tu.type];
      var victims = [];
      if (spl > 0) {
        var sr2 = spl * spl;
        for (var xi = 0; xi < enemies.length; xi++) {
          var x = enemies[xi];
          var xair = E_AIR[x.type];
          if (xair ? !T_AIR[tu.type] : !T_GROUND[tu.type]) continue;
          var xr = ROUTES[xair];
          var xdx = xr.xs[x.progress] - px, xdy = xr.ys[x.progress] - py;
          if (xdx * xdx + xdy * xdy <= sr2) victims.push(x);
        }
      } else victims.push(tgt);
      for (var vj = 0; vj < victims.length; vj++) {
        var v = victims[vj];
        var dmg = pierce ? base : Math.max(1, base - armorOf(v));
        v.hp -= dmg;
        if (slowv > 0) v.slow = slowv;
      }
      tu.cd = T_PER[tu.type];
      if (trace) trace.shots.push([tick, ts, tgt.id, px, py, tu.type, tu.tier]);
      // remove dead in ascending id order
      var dead = false;
      for (var dj = 0; dj < enemies.length; dj++) if (enemies[dj].hp <= 0) { dead = true; break; }
      if (dead) {
        var survivors = [], spawned = [];
        for (var k2 = 0; k2 < enemies.length; k2++) {
          var q = enemies[k2];
          if (q.hp > 0) { survivors.push(q); continue; }
          gold += E_BOUNTY[q.type];
          log.push([tick, 'K', q.id, ts]);
          var qr = ROUTES[E_AIR[q.type]];
          if (trace) trace.kills.push([tick, q.id, q.type, qr.xs[q.progress], qr.ys[q.progress], ts]);
          if (q.type === 4) {
            var shp = Math.max(1, Math.floor(q.maxHp / 4));
            for (var sp = 0; sp < 3; sp++) {
              var ne = makeEnemy(6, q.wave, shp);
              ne.progress = q.progress;
              spawned.push(ne);
            }
          }
        }
        for (var sj = 0; sj < spawned.length; sj++) survivors.push(spawned[sj]);
        enemies = survivors;
      }
    }
    // 6. slow timers
    for (var zi = 0; zi < enemies.length; zi++) if (enemies[zi].slow > 0) enemies[zi].slow--;

    if (trace) {
      var fr = new Float32Array(enemies.length * 7 + 3);
      fr[0] = gold; fr[1] = baseHp; fr[2] = curWave;
      var o = 3;
      for (var fi = 0; fi < enemies.length; fi++) {
        var fe = enemies[fi], frt = ROUTES[E_AIR[fe.type]];
        fr[o++] = fe.id; fr[o++] = fe.type; fr[o++] = frt.xs[fe.progress]; fr[o++] = frt.ys[fe.progress];
        fr[o++] = fe.hp; fr[o++] = fe.maxHp; fr[o++] = fe.slow > 0 ? 1 : 0;
      }
      trace.frames.push(fr);
    }
  }

  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  var score = Math.round((endTick - 20) * 5 / 2) / 100;
  var json = JSON.stringify(log), h = 0x811c9dc5;
  for (var hc = 0; hc < json.length; hc++) { h ^= json.charCodeAt(hc); h = Math.imul(h, 0x01000193); }
  var hash = (h >>> 0).toString(16).padStart(8, '0');
  return { score: score, fallTick: fallTick, log: log, hash: hash };
}

