import asyncio, sys, json, os, time
from playwright.async_api import async_playwright
D = os.path.dirname(os.path.abspath(__file__))

MAIN_JS = """
async ([simSrc, jobs, seeds, maxTicks, nWorkers]) => {
  const workerSrc = `
    let sim = null; const strats = {};
    onmessage = (ev) => {
      const m = ev.data;
      if (m.init) { sim = new Function(m.sim + '; return rampartSimulate;')(); m.jobs.forEach((c, i) => { strats[i] = new Function(c + '; return createStrategy;')(); }); postMessage({ready: 1}); return; }
      const t0 = performance.now();
      let r; try { r = sim(strats[m.job], m.seed, m.maxTicks); } catch (e) { postMessage({job: m.job, seed: m.seed, err: String(e && e.stack || e)}); return; }
      postMessage({job: m.job, seed: m.seed, score: r.score, fall: r.fallTick, ms: performance.now() - t0, hash: r.hash});
    };`;
  const url = URL.createObjectURL(new Blob([workerSrc], {type: 'text/javascript'}));
  const tasks = [];
  for (let j = 0; j < jobs.length; j++) for (const s of seeds) tasks.push({job: j, seed: s, maxTicks});
  const results = [];
  let next = 0;
  await Promise.all(Array.from({length: nWorkers}, () => new Promise((resolve) => {
    const w = new Worker(url);
    const pump = () => {
      if (next >= tasks.length) { w.terminate(); resolve(); return; }
      w.postMessage(tasks[next++]);
    };
    w.onmessage = (ev) => { if (ev.data.ready) { pump(); return; } results.push(ev.data); pump(); };
    w.postMessage({init: 1, sim: simSrc, jobs});
  })));
  return results;
}
"""

class Evaluator:
    def __init__(self, nworkers=9):
        self.sim = open(D + '/sim.js').read()
        self.nw = nworkers
    async def start(self):
        self.pw = await async_playwright().start()
        self.browser = await self.pw.chromium.launch(headless=True)
        self.page = await self.browser.new_page()
        await self.page.goto('about:blank')
    async def stop(self):
        await self.browser.close(); await self.pw.stop()
    async def evaluate(self, codes, seeds, maxTicks=12020):
        res = await self.page.evaluate(MAIN_JS, [self.sim, codes, seeds, maxTicks, self.nw])
        out = [{'scores': {}, 'ms': 0.0, 'errs': []} for _ in codes]
        for r in res:
            o = out[r['job']]
            if 'err' in r: o['errs'].append(r['err']); continue
            o['scores'][r['seed']] = r['score']; o['ms'] = max(o['ms'], r['ms'])
        for o in out:
            v = list(o['scores'].values())
            o['mean'] = sum(v) / len(v) if v else 0.0
            o['min'] = min(v) if v else 0.0
        return out

async def cli():
    files = sys.argv[1].split(',')
    s0, n = int(sys.argv[2]), int(sys.argv[3])
    ev = Evaluator(); await ev.start()
    codes = [open(f).read() for f in files]
    t = time.time()
    out = await ev.evaluate(codes, list(range(s0, s0 + n)))
    for f, o in zip(files, out):
        sc = [o['scores'][k] for k in sorted(o['scores'])]
        print(f, 'mean %.2f min %.2f max %.2f maxms %.0f errs %d' % (o['mean'], o['min'], max(sc) if sc else 0, o['ms'], len(o['errs'])))
        if len(sys.argv) > 4: print(sc)
        if o['errs']: print(o['errs'][0])
    print('time %.1fs' % (time.time() - t))
    await ev.stop()

if __name__ == '__main__':
    asyncio.run(cli())

