import asyncio, sys, json, os
from playwright.async_api import async_playwright
from opt_common import *
D = os.path.dirname(os.path.abspath(__file__))

JS = """
([simSrc, code, seed]) => {
  const sim = new Function(simSrc + '; return rampartSimulate;')();
  const cs = new Function(code + '; return createStrategy;')();
  const trace = {};
  const r = sim(cs, seed, 12020, trace);
  // per wave stats
  const rows = [];
  const types = ['grunt','runner','wisp','brute','splitter','mender','splitling'];
  for (const w of trace.waves) {
    const f = trace.frames[w.tick];
    if (!f) continue;
    let n = 0, hp = 0; const cnt = [0,0,0,0,0,0,0];
    for (let i = 3; i < f.length; i += 7) { n++; hp += f[i+4]; cnt[f[i+1]]++; }
    rows.push([w.wave, w.tick, f[0], f[1], n, Math.round(hp), cnt.join('/')]);
  }
  // turret layout at end
  const lay = {};
  for (const e of r.log) { if (e[1]==='B') lay[e[2]] = ['bolt','cannon','frost','lance','flak'][e[3]]+'1'; if (e[1]==='U') lay[e[2]] = lay[e[2]].slice(0,-1)+e[3]; if (e[1]==='S') delete lay[e[2]]; }
  const leaks = r.log.filter(e => e[1]==='L').map(e => e[0]+':'+types[trace.leaks.find(l=>l[0]===e[0]&&l[1]===e[2])[2]]);
  return {score: r.score, fall: r.fallTick, rows, lay, leaks, kills: r.log.filter(e=>e[1]==='K').length};
}
"""

async def main():
    params = json.loads(sys.argv[1]) if len(sys.argv) > 1 else {'plan': hand_plan(), 'tm': [3,1,4,2,1], 'mender': 1, 'skip': 0}
    seed = int(sys.argv[2]) if len(sys.argv) > 2 else 100
    sim = open(D + '/sim.js').read()
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True)
        pg = await b.new_page()
        r = await pg.evaluate(JS, [sim, make_code(params), seed])
        print('score', r['score'], 'fall', r['fall'], 'kills', r['kills'])
        for row in r['rows']: print(row)
        print(r['lay'])
        print(r['leaks'])
        await b.close()
asyncio.run(main())

