        rockParts.push(part(new THREE.DodecahedronGeometry(1, 0), c, x, y + s * 0.4, z, R() * 3, R() * 6, R() * 3, s, s * (0.6 + R() * 0.4), s));
      } else {
        const s = 0.6 + R() * 0.7, tx = x, tz = z;
        treeParts.push(CY(0.05 * s, 0.08 * s, 0.4 * s, 5, 0x4a3426, tx, y + 0.2 * s, tz));
        treeParts.push(CY(0.0, 0.34 * s, 0.7 * s, 7, 0x1d3a2a, tx, y + 0.65 * s, tz));
        treeParts.push(CY(0.0, 0.26 * s, 0.6 * s, 7, 0x24472f, tx, y + 1.05 * s, tz));
