          dummy.position.set(sx + (i - (tier - 1) / 2) * 0.2, (activeType === 3 ? 1.3 : activeType === 2 ? 1.3 : 1.15), sz + 0.05);
          dummy.quaternion.identity(); const pp = 1 + 0.12 * Math.sin(ts * 5 + s + i); dummy.scale.setScalar(pp); dummy.updateMatrix();
