}

function updateKeep(t, ts) {
  const L = leakInfo, order = W.chunkOrder, chunks = W.chunks, cm = W.chunkMesh;
  let flash = 0, lastLeak = -1;
  for (let j = 0; j < L.length; j++) {
    if (L[j].time <= ts) { lastLeak = j; const a = ts - L[j].time; if (a < 0.45) flash = Math.max(flash, 1 - a / 0.45); }
  }
  const fallen = t >= fallTime, af = fallen ? t - fallTime : 0;
