  let hpScale = 1, tilt = 0;
  if (lastLeak >= 0) {
    const l = L[lastLeak], s0 = 0.55 + 0.45 * l.before / 10, s1 = 0.55 + 0.45 * l.after / 10;
    hpScale = lerp(s0, s1, smooth01((ts - l.time) / 0.3)); tilt = (1 - hpScale) * 0.22;
  }
  W.tower.scale.set(1, hpScale, 1); W.tower.rotation.z = tilt;
  W.corners.scale.set(1, lerp(1, hpScale, 0.7), 1);
  if (fallen) {
    const s = Math.max(0, 1 - af / 0.35);
    W.tower.scale.set(1, hpScale * s, 1); W.corners.scale.set(1, s, 1);
    W.tower.visible = W.corners.visible = af < 0.36;
    // burst of debris and a shockwave
    for (let j = 0; j < 90; j++) {
      const d = DEB[(j * 5 + 3) & 127], d2 = DEB[(j * 11 + 7) & 127];
      addDebris(KEEP.x + d[0] * 0.5, 0.6 + d2[6] * 0.9, KEEP.z + d[2] * 0.5, d[0] * 3.4 + d2[0] * 1.4, d[1] * 1.7, d[2] * 3.4 + d2[2] * 1.4, d[5] * 2.8, j % 3 === 0 ? 0x8a3a30 : j % 3 === 1 ? 0x77737e : 0x55525e, af, 3, d[3] * 0.7, d[4] * 0.7, true);
