      addRing(KEEP.x, 0.1, KEEP.z, 0.3 + 5 * (1 - (1 - u) * (1 - u)), [2.0, 0.5, 0.3], (1 - u) * 0.8);
      addGlow(KEEP.x, 0.9, KEEP.z, 5.5 * (1 - u) + 1, [2.0, 1.0, 0.45], 0.9 * (1 - u));
    }
  } else { W.tower.visible = W.corners.visible = true; }
}

