  W.glow.count = fxN.glow; W.glow.instanceMatrix.needsUpdate = true; W.glow.instanceColor.needsUpdate = true;
  W.debris.count = fxN.deb; W.debris.instanceMatrix.needsUpdate = true; W.debris.instanceColor.needsUpdate = true;

  renderer.clear();
  renderer.render(scene, camera);
