// ================================================================= HUD (drawn in the WebGL canvas, no DOM, no words)
const HUD = { n: 0, max: 420, pos: null, uv: null, col: null, geo: null };
const CELL = { SOLID: 10, COIN: 11, BLADES: 12, PIP: 13, SOFT: 14, ENEMY0: 15 };

function buildHud() {
  hudScene = new THREE.Scene();
  hudCamera = new THREE.OrthographicCamera(0, window.innerWidth, window.innerHeight, 0, -10, 10);
  // ---- glyph atlas on a detached canvas (digits + shape icons), drawn once
  const c = document.createElement('canvas'); c.width = 512; c.height = 256;
  const g = c.getContext('2d');
  const cellXY = function (i) { return [(i % 8) * 64, Math.floor(i / 8) * 64]; };
  g.fillStyle = '#fff'; g.textAlign = 'center'; g.textBaseline = 'middle';
  g.font = 'bold 54px -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif';
  for (let d = 0; d < 10; d++) { const p = cellXY(d); g.fillText(String(d), p[0] + 32, p[1] + 35); }
  let p = cellXY(CELL.SOLID); g.fillRect(p[0], p[1], 64, 64);
  // coin
  p = cellXY(CELL.COIN); {
    const cx = p[0] + 32, cy = p[1] + 32;
    let gr = g.createRadialGradient(cx - 8, cy - 8, 2, cx, cy, 28);
    gr.addColorStop(0, '#fff2a8'); gr.addColorStop(0.55, '#ffc93c'); gr.addColorStop(1, '#c98612');
    g.fillStyle = gr; g.beginPath(); g.arc(cx, cy, 27, 0, 6.2832); g.fill();
    g.strokeStyle = '#8a5a08'; g.lineWidth = 3; g.beginPath(); g.arc(cx, cy, 27, 0, 6.2832); g.stroke();
    g.strokeStyle = '#e8a824'; g.lineWidth = 3; g.beginPath(); g.arc(cx, cy, 19, 0, 6.2832); g.stroke();
    g.fillStyle = '#b8760e'; g.beginPath(); g.moveTo(cx, cy - 11); g.lineTo(cx + 8, cy); g.lineTo(cx, cy + 11); g.lineTo(cx - 8, cy); g.closePath(); g.fill();
  }
  // crossed blades (wave icon)
  p = cellXY(CELL.BLADES); {
    const cx = p[0] + 32, cy = p[1] + 32;
    for (let s = -1; s <= 1; s += 2) {
      g.save(); g.translate(cx, cy); g.rotate(s * 0.78);
      g.fillStyle = '#e9eff7'; g.beginPath(); g.moveTo(0, -29); g.lineTo(5, -20); g.lineTo(5, 14); g.lineTo(-5, 14); g.lineTo(-5, -20); g.closePath(); g.fill();
      g.fillStyle = '#9aa7b8'; g.fillRect(-1.2, -26, 2.4, 40);
      g.fillStyle = '#e0a526'; g.fillRect(-13, 14, 26, 6);
      g.fillStyle = '#a86a14'; g.fillRect(-3.5, 20, 7, 10);
      g.restore();
    }
  }
  // pip (tinted by vertex colour)
  p = cellXY(CELL.PIP); {
    const cx = p[0] + 32, cy = p[1] + 32;
    const gr = g.createRadialGradient(cx - 6, cy - 7, 2, cx, cy, 24);
    gr.addColorStop(0, '#ffffff'); gr.addColorStop(0.6, '#e8e8e8'); gr.addColorStop(1, '#a8a8a8');
    g.fillStyle = gr; g.beginPath(); g.arc(cx, cy, 23, 0, 6.2832); g.fill();
    g.strokeStyle = 'rgba(0,0,0,0.55)'; g.lineWidth = 3; g.beginPath(); g.arc(cx, cy, 23, 0, 6.2832); g.stroke();
  }
  // soft circle
  p = cellXY(CELL.SOFT); {
    const gr = g.createRadialGradient(p[0] + 32, p[1] + 32, 0, p[0] + 32, p[1] + 32, 30);
    gr.addColorStop(0, 'rgba(255,255,255,1)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(p[0], p[1], 64, 64);
  }
  // enemy icons: grunt, runner, wisp, brute, splitter, mender
  const E = function (i, fn) { const q = cellXY(CELL.ENEMY0 + i); g.save(); g.translate(q[0] + 32, q[1] + 32); fn(); g.restore(); };
  const circle = function (r, fill, stroke) { g.fillStyle = fill; g.beginPath(); g.arc(0, 0, r, 0, 6.2832); g.fill(); if (stroke) { g.strokeStyle = stroke; g.lineWidth = 4; g.stroke(); } };
  E(0, function () { circle(24, '#8ea282', '#3d4a36'); g.fillStyle = '#111'; g.fillRect(-11, -6, 7, 7); g.fillRect(4, -6, 7, 7); });
  E(1, function () { g.fillStyle = '#f2cf2e'; g.strokeStyle = '#8a6d00'; g.lineWidth = 4; g.beginPath(); g.moveTo(0, -27); g.lineTo(23, 21); g.lineTo(0, 11); g.lineTo(-23, 21); g.closePath(); g.fill(); g.stroke(); });
  E(2, function () {
    const gr = g.createRadialGradient(0, 0, 2, 0, 0, 30); gr.addColorStop(0, 'rgba(210,255,255,1)'); gr.addColorStop(0.45, 'rgba(70,240,255,0.95)'); gr.addColorStop(1, 'rgba(70,240,255,0)');
    g.fillStyle = gr; g.beginPath(); g.arc(0, 0, 30, 0, 6.2832); g.fill();
  });
  E(3, function () { g.fillStyle = '#34363e'; g.strokeStyle = '#e8742c'; g.lineWidth = 6; g.fillRect(-22, -22, 44, 44); g.strokeRect(-22, -22, 44, 44); g.fillStyle = '#e8742c'; g.fillRect(-14, -4, 28, 8); });
  E(4, function () { circle(18, '#7d3fc4', '#3b1b66'); circle(10, '#b07cf5'); g.save(); g.translate(-14, -16); circle(8, '#b07cf5'); g.restore(); g.save(); g.translate(14, -16); circle(8, '#b07cf5'); g.restore(); });
  E(5, function () { circle(25, '#f4f4f4', '#6fd88a'); g.fillStyle = '#2fbf5a'; g.fillRect(-4, -15, 8, 30); g.fillRect(-15, -4, 30, 8); });
  const tex = new THREE.CanvasTexture(c); tex.encoding = THREE.LinearEncoding; tex.generateMipmaps = false; tex.minFilter = THREE.LinearFilter; tex.magFilter = THREE.LinearFilter;
  HUD.tex = tex;

  const max = HUD.max;
  HUD.pos = new Float32Array(max * 12); HUD.uv = new Float32Array(max * 8); HUD.col = new Float32Array(max * 16);
  const idx = new Uint16Array(max * 6);
  for (let i = 0; i < max; i++) { const b = i * 4; idx.set([b, b + 1, b + 2, b, b + 2, b + 3], i * 6); }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(HUD.pos, 3).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute('uv', new THREE.BufferAttribute(HUD.uv, 2).setUsage(THREE.DynamicDrawUsage));
  geo.setAttribute('aColor', new THREE.BufferAttribute(HUD.col, 4).setUsage(THREE.DynamicDrawUsage));
  geo.setIndex(new THREE.BufferAttribute(idx, 1));
  HUD.geo = geo;
  const mat = new THREE.ShaderMaterial({
    uniforms: { map: { value: tex }, uDesat: DESAT },
    vertexShader: 'attribute vec4 aColor; varying vec2 vUv; varying vec4 vCol; void main(){ vUv = uv; vCol = aColor; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
    fragmentShader: 'uniform sampler2D map; uniform float uDesat; varying vec2 vUv; varying vec4 vCol; void main(){ vec4 c = texture2D(map, vUv) * vCol; float l = dot(c.rgb, vec3(0.299, 0.587, 0.114)); c.rgb = mix(c.rgb, vec3(l), uDesat); gl_FragColor = c; }',
    transparent: true, depthTest: false, depthWrite: false
  });
  const mesh = new THREE.Mesh(geo, mat); mesh.frustumCulled = false;
