// ================================================================= synthesized sound (Web Audio, no files, no music)
const AUDIO = {
  ctx: null, master: null, comp: null, noiseBuf: null, live: new Set(), audible: false, wind: null,
  rng: visRng(4242), shotTimes: [], popTimes: [], lastSimT: 0, lastTick: 0
};

function audioInit() {
  try {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    const ctx = new AC();
    AUDIO.ctx = ctx;
    AUDIO.master = ctx.createGain(); AUDIO.master.gain.value = 0;
    AUDIO.comp = ctx.createDynamicsCompressor();
    AUDIO.comp.threshold.value = -22; AUDIO.comp.knee.value = 20; AUDIO.comp.ratio.value = 8; AUDIO.comp.attack.value = 0.003; AUDIO.comp.release.value = 0.25;
    AUDIO.master.connect(AUDIO.comp); AUDIO.comp.connect(ctx.destination);
    const n = ctx.sampleRate * 2, buf = ctx.createBuffer(1, n, ctx.sampleRate), d = buf.getChannelData(0);
    for (let i = 0; i < n; i++) d[i] = AUDIO.rng() * 2 - 1;
    AUDIO.noiseBuf = buf;
    const res = function () { try { const p = ctx.resume(); if (p && p.catch) p.catch(function () {}); } catch (e) {} };
    res();
    const once = function () { res(); };
    window.addEventListener('pointerdown', once); window.addEventListener('keydown', once);
  } catch (e) { AUDIO.ctx = null; }
}

function aTrack(node) { AUDIO.live.add(node); node.onended = function () { AUDIO.live.delete(node); }; }
function aOut(pan, vol) {
  const ctx = AUDIO.ctx, g = ctx.createGain(); g.gain.value = vol;
  if (ctx.createStereoPanner) { const p = ctx.createStereoPanner(); p.pan.value = clamp(pan, -0.9, 0.9); g.connect(p); p.connect(AUDIO.master); }
  else g.connect(AUDIO.master);
