}
function aOsc(type, f0, f1, t0, dur, vol, pan, atk) {
  const ctx = AUDIO.ctx, o = ctx.createOscillator(); o.type = type;
  o.frequency.setValueAtTime(f0, t0); o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), t0 + dur);
  const g = ctx.createGain(); g.gain.setValueAtTime(0.0001, t0);
  g.gain.linearRampToValueAtTime(vol, t0 + (atk || 0.004)); g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
