  const bq = ctx.createBiquadFilter(); bq.type = ftype; bq.Q.value = q;
  bq.frequency.setValueAtTime(f0, t0); bq.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t0 + dur);
  const g = ctx.createGain(); g.gain.setValueAtTime(0.0001, t0);
  g.gain.linearRampToValueAtTime(vol, t0 + 0.004); g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  src.connect(bq); bq.connect(g); g.connect(aOut(pan, 1));
