}
function playFall() {
  const t = AUDIO.ctx.currentTime + 0.004;
  aOsc('sine', 95, 22, t, 2.0, 0.34, 0.5, 0.01); aOsc('sawtooth', 58, 28, t, 1.5, 0.1, 0.5, 0.02);
  aNoise(t, 2.4, 'lowpass', 500, 60, 0.8, 0.3, 0.5); aNoise(t, 0.4, 'highpass', 700, 700, 0.7, 0.2, 0.5);
