function startWind() {
  if (AUDIO.wind) return;
  const ctx = AUDIO.ctx, src = ctx.createBufferSource(); src.buffer = AUDIO.noiseBuf; src.loop = true;
  const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 340; f.Q.value = 0.9;
  const g = ctx.createGain(); g.gain.value = 0.07;
  const lfo = ctx.createOscillator(); lfo.frequency.value = 0.17; const lg = ctx.createGain(); lg.gain.value = 0.04; lfo.connect(lg); lg.connect(g.gain);
  const lf2 = ctx.createOscillator(); lf2.frequency.value = 0.11; const lg2 = ctx.createGain(); lg2.gain.value = 120; lf2.connect(lg2); lg2.connect(f.frequency);
  src.connect(f); f.connect(g); g.connect(aOut(0, 1));
  src.start(0, 0.3); lfo.start(); lf2.start();
  AUDIO.wind = [src, lfo, lf2];
}
function stopWind(when) { if (!AUDIO.wind) return; AUDIO.wind.forEach(function (n) { try { n.stop(when); } catch (e) {} }); AUDIO.wind = null; }

