  g.cancelScheduledValues(now); g.setValueAtTime(g.value, now);
  if (on) g.linearRampToValueAtTime(0.85, now + 0.03);
  else {
    g.linearRampToValueAtTime(0, now + 0.04);
    AUDIO.live.forEach(function (n) { try { n.stop(now + 0.045); } catch (e) {} });
