  }
}
const SHOT_PRIORITY = [1, 4, 0, 5, 3, 2];   // lower index = louder / more important: lance(3) first
const SHOT_RANK = { 3: 0, 1: 1, 4: 2, 0: 3, 2: 4 };
function rateOk(list, now, limit) {
  while (list.length && list[0] < now - 1.0) list.shift();
  if (list.length >= limit) return false;
  list.push(now); return true;
}
// called every frame; plays one-shots only when forward playback carries simTime across an event tick
function audioFrame(playing, simT) {
  const ctx = AUDIO.ctx; if (!ctx) return;
  audioSetAudible(playing);
  const cur = Math.min(lastTick, Math.floor(Math.min(simT, fallTime) * TPS));
  const fwd = simT >= AUDIO.lastSimT && simT - AUDIO.lastSimT < 0.4;
  if (playing && fwd && ctx.state === 'running') {
    const now = ctx.currentTime, shots = [];
    for (let k = AUDIO.lastTick + 1; k <= cur; k++) {
      const ws = waveStartAt[k]; if (ws) playHorn();
      const lk = leaksAt[k]; if (lk) for (let i = 0; i < lk.length; i++) playLeak();
      const sh = shotsAt[k]; if (sh) for (let i = 0; i < sh.length; i++) shots.push(sh[i]);
      const kl = killsAt[k]; if (kl) for (let i = 0; i < kl.length; i++) if (rateOk(AUDIO.popTimes, now, 14)) playPop(aPan(kl[i][3] / 100));
