    shots.sort(function (a, b) { return SHOT_RANK[a[5]] - SHOT_RANK[b[5]]; });
    for (let i = 0; i < shots.length; i++) if (rateOk(AUDIO.shotTimes, now, 12)) playShot(shots[i][5], aPan(SLOT_TILES[shots[i][1]][0] + 0.5));
