// ================================================================= playback shell (state machine) and boot
const elCountdown = document.getElementById('countdown');
const elToggle = document.getElementById('btn-toggle');
const elPause = document.getElementById('icon-pause');
const elPlay = document.getElementById('icon-play');
const elScrub = document.getElementById('scrubber');
const elRefire = document.getElementById('btn-refire');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

let state = 'COUNTDOWN';          // COUNTDOWN | PLAYING | PAUSED | REFIRE_HOLD | ENDED
let simTime = 0;
let playbackSpeed = 1.0;
let countdownElapsed = 0, holdElapsed = 0, lastNow = null;

function showCountdown(txt) { elCountdown.style.display = 'block'; elCountdown.textContent = txt; }
function hideCountdown() { elCountdown.style.display = 'none'; elCountdown.textContent = ''; }
function setToggleUI(showPause) {
  elPause.style.display = showPause ? 'inline' : 'none';
  elPlay.style.display = showPause ? 'none' : 'inline';
  elToggle.setAttribute('aria-label', showPause ? 'Pause' : 'Play');
}
function setScrub(v) { elScrub.value = v === 0 ? '0' : v.toFixed(3); }
function toPlaying() { state = 'PLAYING'; setToggleUI(true); }
function toPaused() { state = 'PAUSED'; setToggleUI(false); }

function onFrame(now) {
  const raw = lastNow === null ? 0 : (now - lastNow) / 1000;
  lastNow = now;
  const dt = Math.min(Math.max(raw, 0), 0.1);
  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) { hideCountdown(); simTime = 0; setScrub(0); toPlaying(); }
    else showCountdown(String(3 - Math.floor(countdownElapsed)));
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) toPlaying();
  } else if (state === 'PLAYING') {
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    setScrub(simTime);
    if (simTime >= DURATION) { simTime = DURATION; elScrub.value = DURATION.toFixed(3); state = 'ENDED'; setToggleUI(false); }
  }
  try { renderAt(simTime); } catch (err) { console.error(err); }
  audioFrame(state === 'PLAYING', simTime);
  requestAnimationFrame(onFrame);
}

elToggle.addEventListener('click', function () {
  if (state === 'PLAYING') toPaused();
  else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') { hideCountdown(); simTime = 0; setScrub(0); toPaused(); }
  else if (state === 'PAUSED') toPlaying();
  else if (state === 'ENDED') { hideCountdown(); simTime = 0; setScrub(0); toPlaying(); }
});
pills.forEach(function (p) {
  p.addEventListener('click', function () {
    playbackSpeed = parseFloat(p.getAttribute('data-speed'));
    pills.forEach(function (q) {
      const on = q === p;
      q.classList.toggle('is-active', on);
      q.setAttribute('aria-checked', on ? 'true' : 'false');
    });
  });
});
elScrub.addEventListener('input', function () {
  hideCountdown();
  simTime = clamp(parseFloat(elScrub.value) || 0, 0, DURATION);
  toPaused();
  try { renderAt(simTime); } catch (err) { console.error(err); }
});
elRefire.addEventListener('click', function () {
  hideCountdown();
  simTime = 0; setScrub(0);
  holdElapsed = 0; state = 'REFIRE_HOLD'; setToggleUI(true);
  try { renderAt(0); } catch (err) { console.error(err); }
});
function onResize() {
  if (!HAS_GL || !renderer) return;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight, false);
  fitCamera();
  renderAt(simTime);
}
window.addEventListener('resize', onResize);

// ---------------------------------------------------------------- self report
window.BENCH_REPORT = {
  selfCheck: { vectorA: SELF.vectorA, vectorB: SELF.vectorB },
  strategy: /*STRATEGY_REPORT*/ { summary: '', seedsTested: 0, meanScoreOnTestedSeeds: null },
  seed42: { score: simResult.score, fallTick: simResult.fallTick },
  systems: { board: 'full', enemiesAndTurrets: 'full', combatVisuals: 'full', fall: 'full', hud: 'full', audio: 'full' },
  simplifications: [
    'Enemy and turret models are low-poly procedural meshes kept readable at quarter size rather than detailed.',
    'Keep damage shows one knocked-off wall chunk per leak, a lowering/leaning tower and a red flash; no separate crack decals.',
    'HUD pips for base hp are plain gem discs; there are no backing plates behind HUD digits (drop shadows only).'
  ],
  testedInBrowser: /*TESTED*/ false,
  measuredFps: /*FPS*/ null
};

// ---------------------------------------------------------------- boot
(function boot() {
  audioInit();
  if (HAS_GL) {
    try {
      buildWorld();
      buildHud();
      initDynamic();
      fitCamera();
      renderAt(0);                  // initial resting scene, simTime = 0
    } catch (err) { console.error(err); }
  }
  requestAnimationFrame(onFrame);
})();

