function toPaused() { state = 'PAUSED'; setToggleUI(false); }

function onFrame(now) {
  const raw = lastNow === null ? 0 : (now - lastNow) / 1000;
  lastNow = now;
  const dt = Math.min(Math.max(raw, 0), 0.1);
