    uniforms: { map: { value: tex }, uDesat: DESAT },
    vertexShader: 'attribute vec4 aColor; varying vec2 vUv; varying vec4 vCol; void main(){ vUv = uv; vCol = aColor; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
    fragmentShader: 'uniform sampler2D map; uniform float uDesat; varying vec2 vUv; varying vec4 vCol; void main(){ vec4 c = texture2D(map, vUv) * vCol; float l = dot(c.rgb, vec3(0.299, 0.587, 0.114)); c.rgb = mix(c.rgb, vec3(l), uDesat); gl_FragColor = c; }',
    transparent: true, depthTest: false, depthWrite: false
