function hq(x, y, w, h, cell, r, g, b, a) {
  const n = HUD.n; if (n >= HUD.max) return;
  const o = n * 12, col = cell % 8, row = Math.floor(cell / 8);
  const u0 = (col * 64 + 1.5) / 512, u1 = ((col + 1) * 64 - 1.5) / 512, v1 = 1 - (row * 64 + 1.5) / 256, v0 = 1 - ((row + 1) * 64 - 1.5) / 256;
  const P = HUD.pos, U = HUD.uv, C = HUD.col;
  P[o] = x; P[o + 1] = y; P[o + 2] = 0; P[o + 3] = x + w; P[o + 4] = y; P[o + 5] = 0; P[o + 6] = x + w; P[o + 7] = y + h; P[o + 8] = 0; P[o + 9] = x; P[o + 10] = y + h; P[o + 11] = 0;
