// number with soft drop shadow; returns advance width
function hNum(str, x, y, h, r, g, b, a, shadow) {
  const adv = h * 0.58;
  for (let i = 0; i < str.length; i++) {
    const d = str.charCodeAt(i) - 48;
    if (shadow) hq(x + i * adv + h * 0.04, y - h * 0.04, h, h, d, 0, 0, 0, 0.6 * a);
