function drawHud(t, ts, k) {
  const Wd = window.innerWidth, Hd = window.innerHeight;
  HUD.n = 0;
  const A = frames[k];
  const gold = A[0], hp = A[1], wave = A[2];
  const m = 0.022 * Hd, hw = Math.max(0.085 * Hd, 36);
  const x0 = m, yTop = Hd - m;
  // ---- wave number (large) with a crossed-blades icon
  const wst = wave >= 1 ? (20 + 40 * (wave - 1)) / TPS : -9;
  const age = ts - wst, pop = 1 + 0.32 * Math.pow(Math.max(0, 1 - age / 0.4), 2);
  hq(x0 + 0.02 * hw, yTop - hw * 0.98, hw * 0.92, hw * 0.92, CELL.BLADES, 0, 0, 0, 0.5);
  hq(x0, yTop - hw, hw * 0.92, hw * 0.92, CELL.BLADES, 1, 1, 1, 1);
  const wsz = hw * pop;
  hNum(String(wave), x0 + hw * 1.02, yTop - hw - (wsz - hw) * 0.35, wsz, 1.0, 0.93, 0.78, 1, true);
