  hNum(String(gold), x0 + hw * 0.06 + gh * 1.18, gy, gh, 1.0, 0.86, 0.36, 1, true);
  // ---- next-wave preview: coloured enemy icons with counts
  const ph = hw * 0.4, py = gy - ph * 1.3;
  const comp = wave >= 1 ? trace.waves[wave - 1].next : trace.waves[0].comp;
  const counts = [0, 0, 0, 0, 0, 0];
  for (let i = 0; i < comp.length; i++) counts[comp[i]]++;
  let px = x0 + hw * 0.06;
  for (let ty = 0; ty < 6; ty++) {
    if (!counts[ty]) continue;
    hq(px, py, ph, ph, CELL.ENEMY0 + ty, 1, 1, 1, 1);
    const w2 = hNum(String(counts[ty]), px + ph * 1.02, py, ph * 0.9, 0.95, 0.95, 0.98, 1, true);
    px += ph * 1.02 + w2 + ph * 0.32;
  }
