  // ---------------- decor: rocks, pines, gate pillars (seeded)
  {
    const R = visRng(1234);
    const near = function (x, z, minPad, minRoad) {
      for (let s = 0; s < 16; s++) if (Math.hypot(x - SLOT_TILES[s][0] - 0.5, z - SLOT_TILES[s][1] - 0.5) < minPad) return true;
      const gr = ROUTES[0];
