      if (Math.hypot(x - KEEP.x, z - KEEP.z) < 1.9) return true;
      return false;
    };
    const rockParts = [], treeParts = [];
    let placed = 0, guard = 0;
    while (placed < 150 && guard++ < 4000) {
      const x = -6 + R() * 36, z = -5 + R() * 26;
      const inBoard = x > 0 && x < 24 && z > 0 && z < 14;
      if (inBoard && R() < 0.55) continue;
