      const dxo = Math.max(-x, x - 24, 0), dzo = Math.max(-z, z - 14, 0), mask = smooth01((Math.hypot(dxo, dzo) - 0.3) / 7);
      const y = mask * ((vnoise(x * 0.18, z * 0.18, 3) * 2.4 + vnoise(x * 0.45, z * 0.45, 5) + vnoise(x * 1.1, z * 1.1, 8) * 0.25) - 0.2);
      const lum = 0.7 + R() * 0.5, c = ((0x55 * lum) | 0) << 16 | ((0x55 * lum) | 0) << 8 | ((0x60 * lum) | 0);
      if (R() < 0.62) {
        const s = 0.12 + R() * 0.28;
        rockParts.push(part(new THREE.DodecahedronGeometry(1, 0), c, x, y + s * 0.4, z, R() * 3, R() * 6, R() * 3, s, s * (0.6 + R() * 0.4), s));
      } else {
        const s = 0.6 + R() * 0.7, tx = x, tz = z;
