    // gate pillars at the ground spawn and air spawn
    const gate = mergeParts([
      BX(0.4, 1.5, 0.4, 0x5b5963, 0.35, 0.75, 1.55), BX(0.4, 1.5, 0.4, 0x5b5963, 0.35, 0.75, 3.45),
      BX(0.5, 0.25, 2.3, 0x4c4a54, 0.35, 1.55, 2.5), BX(0.3, 0.12, 0.3, 0x7c2a2a, 0.35, 1.8, 1.55), BX(0.3, 0.12, 0.3, 0x7c2a2a, 0.35, 1.8, 3.45),
      BX(0.3, 1.1, 0.3, 0x4c4a54, 0.3, 0.55, 5.9), BX(0.3, 1.1, 0.3, 0x4c4a54, 0.3, 0.55, 7.1), BX(0.4, 0.16, 1.5, 0x3d6a78, 0.3, 1.18, 6.5)
    ]);
    const gm = new THREE.Mesh(gate, matLit); gm.castShadow = true; gm.receiveShadow = true; scene.add(gm);
  }

  // ---------------- the keep (walled, with 16 knock-off chunks)
  {
    const kg = new THREE.Group(); kg.position.set(KEEP.x, 0, KEEP.z); scene.add(kg);
    const matKeep = patchDesat(new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85, metalness: 0.1, flatShading: true, emissive: 0xff1a1a, emissiveIntensity: 0 }));
