      let x, z, ry;
      if (side === 0) { x = s; z = -h; ry = 0; } else if (side === 1) { x = s; z = h; ry = 0; } else if (side === 2) { x = -h; z = s; ry = Math.PI / 2; } else { x = h; z = s; ry = Math.PI / 2; }
