    head: [SP(0.27, 0xc98a47, 0, 0, 0, 1, 0.85, 1), CY(0.12, 0.14, 0.58, 10, 0x8c5a24, 0, 0.0, 0.34, Math.PI / 2, 0, 0), CY(0.17, 0.17, 0.09, 10, 0x4f3214, 0, 0, 0.62, Math.PI / 2, 0, 0)],
    glow: [], hy: 0.6
  };
  // frost (ice-white crystal spire)
  TG[2] = {
