    head: [CY(0.0, 0.15, 0.8, 6, 0xeaf7ff, 0, 0.36, 0), CY(0.0, 0.07, 0.4, 5, 0xcfe9ff, 0.2, 0.06, 0, 0, 0, -0.45), CY(0.0, 0.07, 0.4, 5, 0xcfe9ff, -0.2, 0.06, 0, 0, 0, 0.45),
      CY(0.0, 0.07, 0.4, 5, 0xcfe9ff, 0, 0.06, 0.2, 0.45, 0, 0), CY(0.0, 0.07, 0.4, 5, 0xcfe9ff, 0, 0.06, -0.2, -0.45, 0, 0)],
    glow: [SP(0.08, 0xa8f0ff, 0, 0.82, 0)], hy: 0.4
  };
  // lance (crimson, long rail)
  TG[3] = {
