    head: [BX(0.22, 0.16, 0.4, 0xc0283a, 0, 0, 0), BX(0.07, 0.07, 1.05, 0x7a1523, 0, 0, 0.55), BX(0.02, 0.22, 0.24, 0xe04558, 0, 0.14, -0.14)],
