  W.turrets = [];
  for (let s = 0; s < 16; s++) {
    const row = [];
    for (let t = 0; t < 5; t++) {
      const root = new THREE.Group(); root.position.set(SLOT_TILES[s][0] + 0.5, 0, SLOT_TILES[s][1] + 0.5); root.visible = false;
      if (TG[t].geoBase === undefined) {
