// ================================================================= camera framing
function fitCamera() {
  const w = window.innerWidth, h = window.innerHeight;
  camera.aspect = w / h;
  camera.fov = 38;
  camera.updateProjectionMatrix();
  const pitch = 55 * Math.PI / 180;
  const dir = new THREE.Vector3(0, Math.sin(pitch), Math.cos(pitch));
  const bottom = -1 + 2 * 104 / h, top = 1 - 2 * 6 / h, side = 0.012;
  const corners = [[-0.5, 0, -0.5], [24.5, 0, -0.5], [24.5, 0, 14.5], [-0.5, 0, 14.5], [23.5, 1.9, 11.5], [4, 1.2, 3]];
  const T = new THREE.Vector3(12, 0, 7), P = new THREE.Vector3(), V = new THREE.Vector3();
  const tanHalf = Math.tan(camera.fov * Math.PI / 360);
  function measure(d) {
    let tz = 7, tx = 12, res = null;
    for (let it = 0; it < 14; it++) {
      T.set(tx, 0, tz);
      P.copy(T).addScaledVector(dir, d);
      camera.position.copy(P); camera.lookAt(T); camera.updateMatrixWorld(true);
      let x0 = 9, x1 = -9, y0 = 9, y1 = -9;
      for (const c of corners) { V.set(c[0], c[1], c[2]).project(camera); x0 = Math.min(x0, V.x); x1 = Math.max(x1, V.x); y0 = Math.min(y0, V.y); y1 = Math.max(y1, V.y); }
      const cy = (y0 + y1) / 2, wantY = (bottom + top) / 2;
      const cx = (x0 + x1) / 2;
      res = { x0: x0, x1: x1, y0: y0, y1: y1 };
      tz += (cy - wantY) * d * tanHalf / Math.sin(pitch) * 0.9;
      tx += cx * d * tanHalf * camera.aspect * 0.9;
    }
    return res;
  }
  let lo = 8, hi = 90;
  for (let i = 0; i < 26; i++) {
    const mid = (lo + hi) / 2, r = measure(mid);
    const fits = (r.x1 - r.x0) <= 2 * (1 - side) && (r.y1 - r.y0) <= (top - bottom);
    if (fits) hi = mid; else lo = mid;
  }
  measure(hi);
  camState.pos = camera.position.clone();
  camState.target = T.clone();
  camState.dist = hi;
  camState.right = new THREE.Vector3(); camState.up = new THREE.Vector3();
  camera.matrixWorld.extractBasis(camState.right, camState.up, new THREE.Vector3());
  // HUD camera (pixel space)
  hudCamera.left = 0; hudCamera.right = w; hudCamera.top = h; hudCamera.bottom = 0;
  hudCamera.updateProjectionMatrix();
}

// ================================================================= per-frame scene update (pure function of simTime)
let dummy = null, DEB = null, slotAim0 = null;
const fxN = { beam: 0, ring: 0, glow: 0, deb: 0, shell: 0, pip: 0 };
const ENEMY_BAR_Y = [0.75, 0.55, 0.45, 1.0, 0.85, 1.2, 0.45];
const ENEMY_BAR_W = [0.46, 0.4, 0.4, 0.62, 0.55, 0.46, 0.3];
const DEBRIS_COL = [0x7d8f72, 0xf2cf2e, 0x7ff6ff, 0x4a4c56, 0xa070e0, 0xf0f0f0, 0xb98cff];
const DEBRIS_COL2 = [0x4c5e44, 0xc99a00, 0x35cfe6, 0xe8742c, 0x5f2fa0, 0x58e07a, 0x8a5cd0];
const SHOT_COL = [[1.0, 1.15, 1.6], [1.6, 1.0, 0.4], [0.8, 1.3, 1.8], [2.0, 0.25, 0.3], [0.2, 1.7, 1.5]];

function initDynamic() {
  dummy = new THREE.Object3D();
  const R = visRng(42);
  DEB = [];
  for (let i = 0; i < 128; i++) DEB.push([R() * 2 - 1, 2 + R() * 3.2, R() * 2 - 1, R() * 10 - 5, R() * 10 - 5, 0.05 + R() * 0.07, R()]);
  slotAim0 = [];
  const g = ROUTES[0];
  for (let s = 0; s < 16; s++) {
    const sx = SLOT_TILES[s][0] * 100 + 50, sy = SLOT_TILES[s][1] * 100 + 50;
    let best = 1e18, bi = 0;
    for (let p = 0; p <= g.len; p += 10) { const d = (g.xs[p] - sx) * (g.xs[p] - sx) + (g.ys[p] - sy) * (g.ys[p] - sy); if (d < best) { best = d; bi = p; } }
    slotAim0.push(Math.atan2(g.xs[bi] - sx, g.ys[bi] - sy));
  }
}

function addBeam(x0, y0, z0, x1, y1, z1, w, c) {
  if (fxN.beam >= 700) return;
  const dx = x1 - x0, dy = y1 - y0, dz = z1 - z0, len = Math.sqrt(dx * dx + dy * dy + dz * dz);
  if (len < 1e-4) return;
  dummy.position.set(x0, y0, z0); dummy.quaternion.identity(); dummy.lookAt(x1, y1, z1);
  dummy.scale.set(w, w, len); dummy.updateMatrix();
  W.beams.setMatrixAt(fxN.beam, dummy.matrix); W.beams.instanceColor.setXYZ(fxN.beam, c[0], c[1], c[2]); fxN.beam++;
}
function addRing(x, y, z, radius, c, k) {
  if (fxN.ring >= 700 || radius <= 0.001) return;
  dummy.position.set(x, y, z); dummy.quaternion.identity(); dummy.scale.set(radius, 1, radius); dummy.updateMatrix();
  W.rings.setMatrixAt(fxN.ring, dummy.matrix); W.rings.instanceColor.setXYZ(fxN.ring, c[0] * k, c[1] * k, c[2] * k); fxN.ring++;
}
function addGlow(x, y, z, size, c, k) {
  if (fxN.glow >= 1400 || size <= 0.001) return;
  dummy.position.set(x, y, z); dummy.quaternion.copy(camera.quaternion); dummy.scale.set(size, size, 1); dummy.updateMatrix();
  W.glow.setMatrixAt(fxN.glow, dummy.matrix); W.glow.instanceColor.setXYZ(fxN.glow, c[0] * k, c[1] * k, c[2] * k); fxN.glow++;
}
const _dc = HAS_GL ? new THREE.Color() : null;
function addDebris(x0, y0, z0, vx, vy, vz, size, hex, a, life, sx, sy, rest) {
  if (fxN.deb >= 2600 || a < 0) return;
  if (!rest && a > life) return;
  const gy = size * 0.5, g = 9.8;
  const disc = vy * vy + 2 * g * (y0 - gy);
  const tl = disc > 0 ? (vy + Math.sqrt(disc)) / g : 0;
  const tt = Math.min(a, tl);
  const x = x0 + vx * tt, z = z0 + vz * tt, y = Math.max(gy, y0 + vy * tt - 0.5 * g * tt * tt);
  let s = size;
  if (!rest && a > life * 0.7) s *= 1 - (a - life * 0.7) / (life * 0.3);
  dummy.position.set(x, y, z); dummy.rotation.set(sx * tt, sy * tt, sx * tt * 0.5); dummy.scale.set(s, s * 0.8, s); dummy.updateMatrix();
  W.debris.setMatrixAt(fxN.deb, dummy.matrix);
  _dc.setHex(hex).convertSRGBToLinear();
  W.debris.instanceColor.setXYZ(fxN.deb, _dc.r, _dc.g, _dc.b); fxN.deb++;
}

function snoise(x, seed) { return vnoise(x, 0.37, seed) * 2 - 1; }

function renderAt(t) {
  if (!HAS_GL || !renderer) return;
  t = clamp(t, 0, DURATION);
  const ts = Math.min(t, fallTime);
  const tk = ts * TPS;
  let k = Math.floor(tk), f = tk - k;
  if (k >= lastTick) { k = lastTick; f = 0; }
  const A = frames[k], B = frames[Math.min(k + 1, lastTick)];
  fxN.beam = fxN.ring = fxN.glow = fxN.deb = fxN.shell = fxN.pip = 0;

  // ---- camera shake (trauma^2 * seeded noise of simTime)
  const tr = traumaAt(t), amp = tr * tr * 0.25;
  const ox = amp * snoise(t * 26, 1), oy = amp * snoise(t * 26, 2);
  camera.position.copy(camState.pos).addScaledVector(camState.right, ox).addScaledVector(camState.up, oy);
  camera.updateMatrixWorld(true);
  const qCam = camera.quaternion;
  const rx = camState.right.x, ry = camState.right.y, rz = camState.right.z;

  W.laneTex.offset.x = -ts * 0.7;
  DESAT.value = fallTick >= 0 ? smooth01((t - fallTime) / 1.0) * 0.93 : 0;

  // ---- enemies
  const cnt = [0, 0, 0, 0, 0, 0, 0];
  let nBar = 0, nBlob = 0;
  const na = A.length, nb = B.length;
  let ia = 3, ib = 3;
  while (ia < na || ib < nb) {
    const ida = ia < na ? A[ia] : 1e18, idb = ib < nb ? B[ib] : 1e18;
    let id, type, p, hp, mhp, slow;
    if (ida === idb) {
      id = ida; type = A[ia + 1]; p = lerp(A[ia + 2], B[ib + 2], f); hp = lerp(A[ia + 3], B[ib + 3], f); mhp = A[ia + 4]; slow = f < 0.5 ? A[ia + 5] : B[ib + 5];
      ia += 6; ib += 6;
    } else if (ida < idb) {
      id = ida; type = A[ia + 1]; p = A[ia + 2]; hp = A[ia + 3]; mhp = A[ia + 4]; slow = A[ia + 5];
      ia += 6;
    } else {
      id = idb; type = B[ib + 1]; p = B[ib + 2]; hp = B[ib + 3]; mhp = B[ib + 4]; slow = B[ib + 5];
      ib += 6;
      if (type === 6) continue;          // splitlings appear when their splitter pops
      p = p * f;
    }
    const air = type === 2, route = ROUTES[air ? 1 : 0];
    const head = routeHead(route, air ? 1 : 0, p);
    let x = routeX(route, p), z = routeZ(route, p);
    const jit = (hash01(id) - 0.5) * (type === 3 ? 0.3 : 0.34);
    x += Math.cos(head) * jit; z -= Math.sin(head) * jit;
    let y = 0;
    if (air) y = 0.8 + 0.06 * Math.sin(ts * 3 + id);
    else y = 0.02 * Math.abs(Math.sin(ts * 9 + id));
    let scale = 1;
    if (type === 6) {
      const age = ts - (trace.born[id] || 0) / TPS;
      if (age < 0.4) {
        const u = Math.sin(Math.PI * Math.max(0, age) / 0.4), ang = (id % 3) * 2.094 + hash01(id + 5) * 1.2;
        x += Math.cos(ang) * 0.3 * u; z += Math.sin(ang) * 0.3 * u; y += 0.25 * u;
      }
    }
    const m = W.enemy[type];
    const i = cnt[type];
    if (i < m.userData.cap) {
      dummy.position.set(x, y, z); dummy.rotation.set(0, head, 0); dummy.scale.setScalar(scale); dummy.updateMatrix();
      m.setMatrixAt(i, dummy.matrix);
      if (slow) m.instanceColor.setXYZ(i, 0.5, 0.85, 1.9); else m.instanceColor.setXYZ(i, air ? 1.5 : 1, air ? 1.5 : 1, air ? 1.5 : 1);
      cnt[type]++;
    }
    if (air && nBlob < 500) {
      dummy.position.set(x, 0.035, z); dummy.quaternion.identity(); dummy.scale.set(1, 1, 1); dummy.updateMatrix();
      W.blobs.setMatrixAt(nBlob++, dummy.matrix);
      addGlow(x, y, z, 0.95, [0.2, 0.9, 1.0], 0.8 + 0.2 * Math.sin(ts * 7 + id));
    } else if (type === 5) {
      addGlow(x, 0.3, z, 1.5, [0.2, 0.85, 0.4], 0.55);
    }
    // health bar
    if (nBar < 1500) {
      const frac = clamp(hp / Math.max(1, mhp), 0, 1), bw = ENEMY_BAR_W[type];
      const by = y + ENEMY_BAR_Y[type] + (air ? 0.05 : 0);
      dummy.position.set(x, by, z); dummy.quaternion.copy(qCam); dummy.scale.set(bw + 0.04, 0.09, 1); dummy.updateMatrix();
      W.hpBg.setMatrixAt(nBar, dummy.matrix);
      const fw = Math.max(0.001, bw * frac), shift = -bw / 2 + fw / 2;
      dummy.position.set(x + rx * shift, by + ry * shift, z + rz * shift); dummy.scale.set(fw, 0.06, 1); dummy.updateMatrix();
      W.hpFg.setMatrixAt(nBar, dummy.matrix);
      if (frac > 0.6) W.hpFg.instanceColor.setXYZ(nBar, 0.12, 0.75, 0.2); else if (frac > 0.3) W.hpFg.instanceColor.setXYZ(nBar, 0.9, 0.65, 0.05); else W.hpFg.instanceColor.setXYZ(nBar, 0.9, 0.1, 0.08);
      nBar++;
    }
  }
  for (let ty = 0; ty < 7; ty++) { const m = W.enemy[ty]; m.count = cnt[ty]; m.instanceMatrix.needsUpdate = true; m.instanceColor.needsUpdate = true; }
  W.blobs.count = nBlob; W.blobs.instanceMatrix.needsUpdate = true;
  W.hpBg.count = nBar; W.hpFg.count = nBar;
  W.hpBg.instanceMatrix.needsUpdate = true; W.hpFg.instanceMatrix.needsUpdate = true; W.hpFg.instanceColor.needsUpdate = true;

  // ---- turrets
  const frozen = t >= fallTime;
  for (let s = 0; s < 16; s++) {
    const ty = slotType[k * 16 + s], tier = slotTier[k * 16 + s];
    const sx = SLOT_TILES[s][0] + 0.5, sz = SLOT_TILES[s][1] + 0.5;
    let ghost = -1, ghostA = 0;
    // recent actions on this slot (build/upgrade pop, sell collapse)
    let popA = 9, sellA = 9, sellType = -1;
    for (let kk = Math.max(0, k - 15); kk <= k; kk++) {
      const acts = actsAt[kk]; if (!acts) continue;
      for (let ai = 0; ai < acts.length; ai++) {
        const e = acts[ai]; if (e[2] !== s) continue;
        const a = ts - kk / TPS;
        if (e[1] === 'S') { if (a < sellA) { sellA = a; sellType = slotType[Math.max(0, kk - 1) * 16 + s]; } }
        else if (a < popA) popA = a;
        const cc = e[1] === 'S' ? [0.8, 0.8, 0.85] : e[1] === 'B' ? [1.0, 0.85, 0.35] : [0.55, 1.0, 0.9];
        if (a >= 0 && a < 0.75) {
          if (e[1] === 'S') {
            for (let j = 0; j < 8; j++) { const d = DEB[(s * 13 + j * 5 + kk) & 127]; addDebris(sx, 0.45, sz, d[0] * 1.3, d[1] * 0.4, d[2] * 1.3, d[5] * 2.4, 0x6d6e78, a, 0.75, d[3], d[4], false); }
            addRing(sx, 0.08, sz, lerp(0.3, 0.9, a / 0.75), [0.8, 0.8, 0.85], 1 - a / 0.75);
          } else {
            addRing(sx, 0.08, sz, lerp(0.25, 1.15, smooth01(a / 0.5)), cc, clamp(1 - a / 0.5, 0, 1));
            for (let j = 0; j < 7; j++) {
              const h = hash01(s * 31 + j * 7 + kk), ang = h * 6.283, rad = 0.2 + 0.25 * hash01(j + kk * 3), u = a / 0.75;
              addGlow(sx + Math.cos(ang) * rad, 0.15 + u * 1.3 * (0.7 + 0.5 * hash01(j + 9)), sz + Math.sin(ang) * rad, 0.2 * (1 - u * 0.6), cc, 1.4 * (1 - u));
            }
          }
        }
      }
    }
