import asyncio, sys, json, os
from playwright.async_api import async_playwright
from opt_common import make_code
from opt2 import to_params
D = os.path.dirname(os.path.abspath(__file__))

JS = """
([simSrc, code, seed]) => {
  const sim = new Function(simSrc + '; return rampartSimulate;')();
  const cs = new Function(code + '; return createStrategy;')();
  const trace = {};
  const r = sim(cs, seed, 12020, trace);
  const F = r.fallTick;
  const per = [8, 24, 12, 36, 10];
  const names = ['bolt','cannon','frost','lance','flak'];
  // final type per slot
  const lay = {};
  for (const e of r.log) { if (e[1]==='B') lay[e[2]] = e[3]; if (e[1]==='S') delete lay[e[2]]; }
  const win = 400;
  const cnt = {};
  for (const s of trace.shots) if (s[0] > F - win && s[0] <= F) cnt[s[1]] = (cnt[s[1]]||0) + 1;
  const rows = [];
  for (let s = 0; s < 16; s++) { const t = lay[s]; rows.push([s, t == null ? '-' : names[t], cnt[s]||0, t==null?0:Math.floor(win/per[t])]); }
  // kills by type in last window and leaks
  const types = ['grunt','runner','wisp','brute','splitter','mender','splitling'];
  const leaks = trace.leaks.map(l => l[0] + ':' + types[l[2]]);
  // enemies alive composition at F-200
  const fr = trace.frames[Math.max(0, F - 200)];
  const comp = [0,0,0,0,0,0,0]; let hp = 0;
  for (let i = 3; i < fr.length; i += 6) { comp[fr[i+1]]++; hp += fr[i+3]; }
  return {score: r.score, F, rows, leaks, comp: comp.join('/'), hp: Math.round(hp)};
}
"""

