import asyncio, sys, json, random, copy, time, os, math
from batch import Evaluator
from opt_common import make_code, DEFAULT_TW, D

def to_params(st):
    return {'plan': st['plan'], 'tw': st['tw'], 'dg': st['dg'], 'skip': st['skip'], 'cap': st.get('cap', 80)}

def convert_v1(st):
    plan = [[s, st['types'][s], tier] for s, tier in st['order']]
    return {'plan': plan, 'tw': st['tw'], 'dg': [[0] * 8 for _ in range(5)], 'skip': st['skip'], 'cap': st.get('cap', 80)}

def random_state(rng):
    w = [0.2, 0.3, 0.12, 0.2, 0.18]
    types = [rng.choices(range(5), w)[0] for _ in range(16)]
    order = list(range(16)); rng.shuffle(order)
    plan = [[s, types[s], 1] for s in order]
    ups = [[s, types[s], t] for t in (2, 3) for s in order]
    # keep tier-2 before tier-3 per slot but interleave a bit
    for _ in range(40):
        i, j = rng.randrange(16, 48), rng.randrange(16, 48)
        plan2 = plan + ups
        ups[i - 16], ups[j - 16] = ups[j - 16], ups[i - 16]
    return {'plan': plan + ups, 'tw': copy.deepcopy(DEFAULT_TW), 'dg': [[0] * 8 for _ in range(5)], 'skip': 0, 'cap': 80}

def mutate(st, rng, focus):
    st = copy.deepcopy(st)
    n = rng.choice([1, 1, 2, 3])
    plan = st['plan']
    for _ in range(n):
        r = rng.random()
        if focus == 'plan': r *= 0.62
        elif focus == 'tw': r = 0.62 + r * 0.38
        if r < 0.12:
            i, j = rng.randrange(len(plan)), rng.randrange(len(plan))
            plan[i], plan[j] = plan[j], plan[i]
        elif r < 0.26:
            i = rng.randrange(len(plan))
            j = min(len(plan) - 1, max(0, i + rng.randint(-8, 8)))
            x = plan.pop(i); plan.insert(j, x)
        elif r < 0.42:
            i = rng.randrange(len(plan)); s = plan[i][0]; nt = rng.choice([t for t in range(5) if t != plan[i][1]])
            for j in range(i, len(plan)):
                if plan[j][0] == s: plan[j][1] = nt
        elif r < 0.50:
            s = rng.randrange(16)
            last = [p for p in plan if p[0] == s]
            if last:
                lt = last[-1][1]; nt = rng.choice([t for t in range(5) if t != lt])
                pos = rng.randrange(int(len(plan) * 0.5), len(plan) + 1)
                plan.insert(pos, [s, nt, rng.choice([2, 3, 3])])
        elif r < 0.54:
            if len(plan) > 20:
                plan.pop(rng.randrange(len(plan)))
        elif r < 0.56:
            st['skip'] = 1 - st['skip']
        elif r < 0.62:
            # tier tweak on a step
            i = rng.randrange(len(plan)); plan[i][2] = rng.choice([1, 2, 3])
        else:
            key = 'tw' if rng.random() < 0.65 else 'dg'
            t = rng.randrange(5); k = rng.randrange(8)
            w = st[key][t][k]
            if rng.random() < 0.3: w = 0.0 if abs(w) > 0 and rng.random() < 0.3 else w + rng.gauss(0, 1.0)
            else: w = w + rng.gauss(0, 0.4 * max(abs(w), 0.5))
            st[key][t][k] = round(w, 3)
    return st

async def main():
    tag = sys.argv[1]; gens = int(sys.argv[2]); pop = int(sys.argv[3]); focus = sys.argv[4]; init = sys.argv[5]
    seeds = [s for s in range(1, 41)]
    rng = random.Random(abs(hash(tag)) & 0xffff)
    if init.startswith('random:'):
        st = random_state(random.Random(int(init.split(':')[1])))
    else:
        st = json.load(open(init))
        if 'order' in st: st = convert_v1(st)
    ev = Evaluator(); await ev.start()
    out = await ev.evaluate([make_code(to_params(st))], seeds)
    cur = out[0]['mean']
    print('start', cur, flush=True)
    t0 = time.time()
    last_imp = 0
    for g in range(gens):
        cands = [mutate(st, rng, focus) for _ in range(pop)]
        out = await ev.evaluate([make_code(to_params(c)) for c in cands], seeds)
        bi = max(range(pop), key=lambda i: out[i]['mean'])
        m = out[bi]['mean']
        if m > cur + 1e-9 or (m >= cur - 1e-9 and rng.random() < 0.5):
            if m > cur + 1e-9:
                last_imp = g
                print('gen %d  %.3f -> %.3f  (min %.2f, %.0fs)' % (g, cur, m, out[bi]['min'], time.time() - t0), flush=True)
            cur = m; st = cands[bi]
            json.dump(st, open(D + '/best2_%s.json' % tag, 'w'))
        if g - last_imp > 250: break
    print('final', cur, flush=True)
    await ev.stop()
asyncio.run(main())

