  const COST = [50, 90, 70, 120, 80];
  const DMG = [26, 60, 10, 180, 40];
  const SPL = [0, 90, 0, 0, 70];
  const TIDX = { bolt: 0, cannon: 1, frost: 2, lance: 3, flak: 4 };
  const LEAK = { grunt: 1, runner: 1, wisp: 2, brute: 3, splitter: 2, mender: 2, splitling: 1 };
  const done = [];
  let hpNow = 10;

  function tierDmg(t, tier) { let d = DMG[t]; for (let i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }

  return {
    plan(state) {
      hpNow = state.baseHp;
      const acts = [];
      let gold = state.gold;
      const cur = state.slots.map(s => s.turret ? { type: TIDX[s.turret.type], tier: s.turret.tier, spent: s.turret.spent } : null);
      for (let i = 0; i < P.plan.length; i++) {
        if (done[i]) continue;
        const st = P.plan[i];
        const slot = st[0], type = st[1], tier = st[2];
        let c = cur[slot];
        if (c && c.type === type && c.tier >= tier) { done[i] = 1; continue; }
        let avail = gold;
        let needSell = false;
        if (c && c.type !== type) { avail += Math.floor(c.spent * 70 / 100); needSell = true; }
        let cost = 0;
        let t0 = needSell || !c ? 0 : c.tier;
        if (t0 === 0) { cost += COST[type]; t0 = 1; }
        while (t0 < tier) { cost += t0 === 1 ? COST[type] : 2 * COST[type]; t0++; }
        if (cost > avail) {
          if (P.skip) continue;
          break;
        }
        if (needSell) { acts.push({ op: 'sell', slot }); gold += Math.floor(c.spent * 70 / 100); c = null; }
        gold -= cost;
        let have = c ? c.tier : 0;
        if (!c) { acts.push({ op: 'build', slot, type: NAMES[type] }); cur[slot] = { type, tier: 1, spent: COST[type] }; have = 1; }
        let spent = cur[slot].spent;
        while (have < tier) { acts.push({ op: 'upgrade', slot }); spent += have === 1 ? COST[type] : 2 * COST[type]; have++; }
        cur[slot] = { type, tier: have, spent };
        done[i] = 1;
      }
      return acts.slice(0, 32);
    },
    target(turret, cands) {
      const t = TIDX[turret.type];
      const n = cands.length;
      if (n === 1) return cands[0].id;
      const W0 = P.tw[t], DG = P.dg ? P.dg[t] : null;
      const danger = (10 - hpNow) / 10;
      const W = [];
      for (let i = 0; i < 8; i++) W.push(W0[i] + (DG ? DG[i] * danger : 0));
      const dmg = tierDmg(t, turret.tier);
      const spl = SPL[t], spl2 = spl * spl;
      const pierce = t === 3;
      const lim = Math.min(n, P.cap || 80);
      let best = -1, bestV = -1e18;
      for (let i = 0; i < n; i++) {
        const e = cands[i];
        const eff = pierce ? dmg : Math.max(1, dmg - e.armor);
        let f1;
        if (spl > 0 && i < lim) {
          f1 = 0;
          for (let j = 0; j < lim; j++) {
            const o = cands[j];
            const dx = o.x - e.x, dy = o.y - e.y;
            if (dx * dx + dy * dy <= spl2) f1 += Math.min(o.hp, pierce ? dmg : Math.max(1, dmg - o.armor)) / dmg;
          }
        } else f1 = Math.min(e.hp, eff) / dmg;
        const prog = 1 - e.remaining / (e.air ? 2800 : 4600);
        const v = W[0] * f1 + W[1] * prog + W[2] * Math.log(1 + e.hp) + (e.type === 'mender' ? W[3] : 0)
          + (e.slowed ? 0 : W[4]) + (eff >= e.hp ? W[5] : 0) + W[6] * LEAK[e.type] + W[7] * (e.type === 'brute' ? 1 : 0);
        if (v > bestV) { bestV = v; best = e.id; }
      }
      return best;
    }
  };
}

