import asyncio, sys, json, random, copy, time, os, math
from batch import Evaluator
from opt_common import make_code, D

NW = 13

def to_params(st):
    return {'plan': st['plan'], 'tw': st['tw'], 'dg': st['dg'], 'skip': st['skip'], 'cap': st.get('cap', 80), 'prior': st.get('prior', 40)}

def normalize(st):
    for key in ('tw', 'dg'):
        for row in st[key]:
            while len(row) < NW: row.append(0.0)
    return st

def last_type(plan, s):
    t = None
    for p in plan:
        if p[0] == s and p[1] >= 0: t = p[1]
    return t

def mutate(st, rng, focus):
    st = copy.deepcopy(st)
    n = rng.choice([1, 1, 2, 3])
    plan = st['plan']
    for _ in range(n):
        r = rng.random()
        if focus == 'plan': r *= 0.66
        elif focus == 'tw': r = 0.66 + r * 0.34
        if r < 0.10:
            i, j = rng.randrange(len(plan)), rng.randrange(len(plan))
            plan[i], plan[j] = plan[j], plan[i]
        elif r < 0.22:
            i = rng.randrange(len(plan))
            j = min(len(plan) - 1, max(0, i + rng.randint(-8, 8)))
            x = plan.pop(i); plan.insert(j, x)
        elif r < 0.34:
            i = rng.randrange(len(plan))
            if plan[i][1] >= 0:
                s = plan[i][0]; nt = rng.choice([t for t in range(5) if t != plan[i][1]])
                for j in range(i, len(plan)):
                    if plan[j][0] == s and plan[j][1] >= 0:
                        plan[j][1] = nt
        elif r < 0.40:
            s = rng.randrange(16)
            lt = last_type(plan, s)
            if lt is not None:
                nt = rng.choice([t for t in range(5) if t != lt])
                pos = rng.randrange(int(len(plan) * 0.5), len(plan) + 1)
                plan.insert(pos, [s, nt, rng.choice([2, 3, 3])])
        elif r < 0.43:
            if len(plan) > 20: plan.pop(rng.randrange(len(plan)))
        elif r < 0.44:
            st['skip'] = 1 - st['skip']
        elif r < 0.47:
            i = rng.randrange(len(plan)); plan[i][2] = rng.choice([1, 2, 3])
        elif r < 0.55:
            # flexify a concrete build step
            idx = [i for i, p in enumerate(plan) if p[1] >= 0 and len(p) == 3 and p[2] == 1]
            if idx:
                i = rng.choice(idx); s = plan[i][0]; a = plan[i][1]
                b = rng.choice([t for t in range(5) if t != a])
                plan[i] = [s, a, 1, b, round(rng.uniform(0.07, 0.22), 3)]
                for j in range(i + 1, len(plan)):
                    if plan[j][0] == s and plan[j][1] >= 0 and len(plan[j]) == 3: plan[j][1] = -1
        elif r < 0.58:
            idx = [i for i, p in enumerate(plan) if len(p) > 3]
            if idx:
                i = rng.choice(idx); s = plan[i][0]; a = plan[i][1]
                plan[i] = [s, a, plan[i][2]]
                for j in range(i + 1, len(plan)):
                    if plan[j][0] == s and plan[j][1] < 0: plan[j][1] = a
        elif r < 0.64:
            idx = [i for i, p in enumerate(plan) if len(p) > 3]
            if idx:
                i = rng.choice(idx)
                plan[i][4] = round(min(0.3, max(0.0, plan[i][4] + rng.gauss(0, 0.025))), 3)
                if rng.random() < 0.15:
                    plan[i][1], plan[i][3] = plan[i][3], plan[i][1]
        else:
            key = 'tw' if rng.random() < 0.65 else 'dg'
            t = rng.randrange(5); k = rng.randrange(NW)
            w = st[key][t][k]
            if rng.random() < 0.3: w = 0.0 if abs(w) > 0 and rng.random() < 0.3 else w + rng.gauss(0, 1.0)
            else: w = w + rng.gauss(0, 0.4 * max(abs(w), 0.5))
            st[key][t][k] = round(w, 3)
    return st

async def main():
    tag = sys.argv[1]; gens = int(sys.argv[2]); pop = int(sys.argv[3]); focus = sys.argv[4]; init = sys.argv[5]
    nseeds = int(sys.argv[6]) if len(sys.argv) > 6 else 60
    seeds = [s for s in range(1, nseeds + 1) if s != 42]
    rng = random.Random(abs(hash(tag)) & 0xffff)
    st = normalize(json.load(open(init)))
    ev = Evaluator(nworkers=int(os.environ.get('NW', '7'))); await ev.start()
    out = await ev.evaluate([make_code(to_params(st))], seeds)
    cur = out[0]['mean']
    print('start', cur, flush=True)
    t0 = time.time(); last_imp = 0
    for g in range(gens):
        cands = [mutate(st, rng, focus) for _ in range(pop)]
        out = await ev.evaluate([make_code(to_params(c)) for c in cands], seeds)
        bi = max(range(pop), key=lambda i: out[i]['mean'])
        m = out[bi]['mean']
        if m > cur + 1e-9 or (m >= cur - 1e-9 and rng.random() < 0.5):
            if m > cur + 1e-9:
                last_imp = g
                print('gen %d  %.3f -> %.3f  (min %.2f, %.0fs)' % (g, cur, m, out[bi]['min'], time.time() - t0), flush=True)
            cur = m; st = cands[bi]
            json.dump(st, open(D + '/best3_%s.json' % tag, 'w'))
        if g - last_imp > 300: break
    print('final', cur, flush=True)
    await ev.stop()

if __name__ == '__main__':
    asyncio.run(main())

