import asyncio, sys, json, os, time
from playwright.async_api import async_playwright
THREE = '/private/tmp/pcd-sbx-claude-sonnet-5.5-xhigh-r2-7ggu4dcc/tmp/three-dl/three.min.js'
HTML = 'file:///private/tmp/pcd-sbx-claude-sonnet-5.5-xhigh-r2-7ggu4dcc/work/index.html'

JS = """async () => {
  const out = {};
  await AUDIO.ctx.resume();
  out.ctx = AUDIO.ctx.state;
  // count voices through monkey patches
  const counts = {shot: 0, pop: 0, horn: 0, leak: 0, fall: 0, wind: 0};
  const orig = { shot: playShot, pop: playPop, horn: playHorn, leak: playLeak, fall: playFall, wind: startWind };
  playShot = function () { counts.shot++; return orig.shot.apply(null, arguments); };
  playPop = function () { counts.pop++; return orig.pop.apply(null, arguments); };
  playHorn = function () { counts.horn++; return orig.horn.apply(null, arguments); };
  playLeak = function () { counts.leak++; return orig.leak.apply(null, arguments); };
  playFall = function () { counts.fall++; return orig.fall.apply(null, arguments); };
  startWind = function () { counts.wind++; return orig.wind.apply(null, arguments); };
  // simulate forward playback in 60 Hz steps from 30 s to 33 s (wall time not advancing -> rate limiter is stressed)
  AUDIO.lastSimT = 30; AUDIO.lastTick = Math.floor(30 * TPS);
  let t = 30, maxLive = 0;
  for (let i = 0; i < 180; i++) { t += 1 / 60; audioFrame(true, t); maxLive = Math.max(maxLive, AUDIO.live.size); }
  out.counts30 = Object.assign({}, counts); out.maxLive = maxLive;
  out.audible = AUDIO.audible; out.gainTarget = AUDIO.master.gain.value;
  // pause -> mute, nodes stopped
  audioFrame(false, t);
  out.afterPause = { audible: AUDIO.audible, live: AUDIO.live.size };
  await new Promise(r => setTimeout(r, 120));
  out.gainAfter = AUDIO.master.gain.value;
  // scrub (jump) must not trigger
  const before = counts.shot + counts.pop + counts.horn + counts.leak;
  audioFrame(true, 60.0); audioFrame(true, 60.02);
