import asyncio, sys, json, os, time
from playwright.async_api import async_playwright
THREE = '/private/tmp/pcd-sbx-claude-sonnet-5.5-xhigh-r2-7ggu4dcc/tmp/three-dl/three.min.js'
HTML = 'file:///private/tmp/pcd-sbx-claude-sonnet-5.5-xhigh-r2-7ggu4dcc/work/index.html'
GPU = os.environ.get('GPU', 'swiftshader')

JS = """() => {
  const out = {};
  // max enemies alive in the replay
  let mx = 0, mxk = 0; for (let k = 0; k < frames.length; k++) { const n = (frames[k].length - 3) / 6; if (n > mx) { mx = n; mxk = k; } }
  out.maxEnemies = mx; out.atTick = mxk;
  const t = mxk / 20;
  // JS-only cost: time the scene update excluding GL calls by stubbing render
  const rr = renderer.render.bind(renderer);
  renderer.render = function () {};
  let t0 = performance.now();
  for (let i = 0; i < 60; i++) renderAt(t + i * 0.001);
  out.jsMsPerFrame = (performance.now() - t0) / 60;
  renderer.render = rr;
  return out;
}"""

async def main():
    args = ['--ignore-gpu-blocklist']
    if GPU == 'swiftshader': args += ['--enable-unsafe-swiftshader', '--use-angle=swiftshader']
    elif GPU == 'metal': args += ['--use-angle=metal']
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True, args=args)
        pg = await b.new_page(viewport={'width': 1920, 'height': 1080})
        async def route(r): await r.fulfill(path=THREE, content_type='application/javascript')
        await pg.route('**/three.min.js', route)
        await pg.goto(HTML)
        await pg.wait_for_timeout(1500)
        await pg.click('#btn-toggle')
        r = await pg.evaluate(JS)
        print(json.dumps(r))
        info = await pg.evaluate("""() => { const c = document.createElement('canvas'); const gl = c.getContext('webgl'); const e = gl.getExtension('WEBGL_debug_renderer_info'); return gl.getParameter(e.UNMASKED_RENDERER_WEBGL); }""")
        print(info)
        # real frame rate over 2 s of playback at late game
        await pg.evaluate("""() => { const s = document.getElementById('scrubber'); s.value = 80; s.dispatchEvent(new Event('input', {bubbles: true})); }""")
        fps = await pg.evaluate("""() => new Promise(res => { document.getElementById('btn-toggle').click(); let n = 0; const t0 = performance.now(); function f() { n++; if (performance.now() - t0 < 3000) requestAnimationFrame(f); else res(n / 3); } requestAnimationFrame(f); })""")
        print('fps (this environment):', fps)
        await b.close()
asyncio.run(main())

