  const w = innerWidth, h = innerHeight;
  camera.position.copy(camState.pos); camera.updateMatrixWorld(true);
  const pts = [[-0.5,0,-0.5],[24.5,0,-0.5],[24.5,0,14.5],[-0.5,0,14.5],[0,0,0],[24,0,0],[24,0,14],[0,0,14]];
  const out = pts.map(p => { const v = new THREE.Vector3(p[0],p[1],p[2]).project(camera); return [Math.round((v.x+1)/2*w), Math.round((1-v.y)/2*h)]; });
