  return { w, h, minX: Math.min(...xs.slice(0,4)), maxX: Math.max(...xs.slice(0,4)), minY: Math.min(...ys.slice(0,4)), maxY: Math.max(...ys.slice(0,4)), bottomClear: h - Math.max(...ys.slice(0,4)), pitch: 55, fov: camera.fov };
