import asyncio, sys, json, copy, os
from playwright.async_api import async_playwright
import batch
from opt_common import make_code
from opt3 import to_params, normalize
D = os.path.dirname(os.path.abspath(__file__))

JS = """
([simSrc, code, seed]) => {
  const sim = new Function(simSrc + '; return rampartSimulate;')();
  const cs = new Function(code + '; return createStrategy;')();
  const trace = {};
  const r = sim(cs, seed, 12020, trace);
  const names = ['bolt','cannon','frost','lance','flak'];
  const lay = {};
  for (const e of r.log) { if (e[1]==='B') lay[e[2]] = names[e[3]]+'1'; if (e[1]==='U') lay[e[2]] = lay[e[2]].slice(0,-1)+e[3]; if (e[1]==='S') delete lay[e[2]]; }
  const rows = [];
  for (const w of trace.waves) { if (w.wave % 5 !== 0) continue; const f = trace.frames[w.tick]; if (!f) continue; let n=0, hp=0; for (let i=3;i<f.length;i+=6){n++;hp+=f[i+3];} rows.push([w.wave, f[0], n, Math.round(hp)]); }
  const kills = r.log.filter(e=>e[1]==='K').length;
  return {score: r.score, lay, rows, kills, acts: r.log.filter(e=>e[1]!=='K'&&e[1]!=='L').length};
}
"""

async def main():
    st = normalize(json.load(open(sys.argv[1])))
    seed = int(sys.argv[2])
    code = make_code(to_params(st))
    sim0 = open(D + '/sim.js').read()
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True)
        pg = await b.new_page()
        for gold in (250, 1000000):
            sim = sim0.replace('var baseHp = 10, gold = 250,', 'var baseHp = 10, gold = %d,' % gold)
            r = await pg.evaluate(JS, [sim, code, seed])
            print('gold', gold, 'score', r['score'], 'kills', r['kills'], 'acts', r['acts'])
            print(sorted(r['lay'].items(), key=lambda kv: int(kv[0])))
            print(r['rows'])
        await b.close()
asyncio.run(main())

