import asyncio, sys, json, os
from playwright.async_api import async_playwright
D = os.path.dirname(os.path.abspath(__file__))
sim0 = open(D + '/sim.js').read()

JS = """
(simSrc) => {
  const sim = new Function(simSrc + '; return rampartSimulate;')();
  const csA = () => ({ plan(s) { const a = []; let g = s.gold; for (const sl of s.slots) if (!sl.turret && g >= 50) { a.push({ op: "build", slot: sl.slot, type: "bolt" }); g -= 50; } return a; } });
  const rA = sim(csA, 42, 12020);
  const csB = () => ({ plan(s) {
    if (s.wave === 1) return [{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}];
    if (s.wave === 3) return [{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}];
    if (s.wave === 6) return [{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}];
    return []; } });
  const rB = sim(csB, 7, 12020);
  return [rA.hash, rA.score, rB.hash, rB.score];
}
"""

VARIANTS = {
  'baseline': (None, None),
