import json, sys, os
from opt_common import TEMPLATE
from opt3 import to_params, normalize
D = os.path.dirname(os.path.abspath(__file__))

HEADER = """// Last Rampart strategy.
// A priority-ordered build / upgrade / swap plan (executed step by step as gold allows, never more than
// 32 actions per wave), with a few "flexible" build steps that pick their turret type from the air share
// observed in the revealed wave compositions, plus a per-turret-type target scorer:
//   score = w0*splash_value + w1*progress + w2*log(hp) + per-enemy-type bonus + unslowed bonus + kill bonus + leak weight,
// where the weights were tuned offline by simulation (training seeds 1-60, validated on unseen seeds).
// It is self-contained: no window / document / THREE / Math.random / Date / performance.
"""

def fmt_p(params):
    lines = ['const P = {']
    plan = params['plan']
    chunks = []
    for i in range(0, len(plan), 6):
        chunks.append('    ' + ', '.join(json.dumps(s, separators=(',', ':')) for s in plan[i:i + 6]))
    lines.append('  plan: [\n' + ',\n'.join(chunks) + '\n  ],')
    lines.append('  tw: [\n' + ',\n'.join('    ' + json.dumps(r, separators=(',', ':')) for r in params['tw']) + '\n  ],')
    lines.append('  dg: [\n' + ',\n'.join('    ' + json.dumps(r, separators=(',', ':')) for r in params['dg']) + '\n  ],')
    lines.append('  skip: %d, cap: %d, prior: %d' % (params['skip'], params['cap'], params['prior']))
    lines.append('};')
    return '\n'.join('  ' + l if i else '  ' + l for i, l in enumerate(lines))

def main():
    st = normalize(json.load(open(sys.argv[1])))
    params = to_params(st)
    code = TEMPLATE.replace('/*PARAMS*/', fmt_p(params).lstrip())
    code = HEADER + code
    out = sys.argv[2] if len(sys.argv) > 2 else os.path.join(D, 'strategy_final.js')
    open(out, 'w').write(code)
    print('wrote', out, len(code))

main()

