import asyncio, sys, json, os
from playwright.async_api import async_playwright
from opt_common import make_code
from opt3 import to_params, normalize
D = os.path.dirname(os.path.abspath(__file__))
sim = open(D + '/sim.js').read()

JS = """
([simSrc, code, seeds]) => {
  const sm = new Function(simSrc + '; return rampartSimulate;')();
  const cs = new Function(code + '; return createStrategy;')();
  const out = [];
  for (const seed of seeds) {
    const trace = {};
    const r = sm(cs, seed, 12020, trace);
    // air share and brute share, mender share over waves 3..30 (revealed waves)
    let air = 0, all = 0, brute = 0, mender = 0, runner = 0, split = 0;
    for (const w of trace.waves) { if (w.wave < 3 || w.wave > 30) continue; for (const t of w.comp) { all++; if (t === 2) air++; if (t === 3) brute++; if (t === 5) mender++; if (t === 1) runner++; if (t === 4) split++; } }
    out.push([seed, r.score, air / all, brute / all, mender / all, runner / all, split / all]);
  }
  return out;
}
"""

def corr(a, b):
    n = len(a); ma = sum(a) / n; mb = sum(b) / n
    sa = sum((x - ma) ** 2 for x in a) ** 0.5; sb = sum((y - mb) ** 2 for y in b) ** 0.5
    return sum((x - ma) * (y - mb) for x, y in zip(a, b)) / (sa * sb)

async def main():
    st = normalize(json.load(open(sys.argv[1])))
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True)
        pg = await b.new_page()
        rows = await pg.evaluate(JS, [sim, make_code(to_params(st)), list(range(200, 300))])
        sc = [r[1] for r in rows]
        for i, name in enumerate(['air', 'brute', 'mender', 'runner', 'splitter']):
            print('%-9s corr with score %.3f   mean share %.3f  std %.3f' % (name, corr([r[2 + i] for r in rows], sc), sum(r[2 + i] for r in rows) / len(rows), (sum((r[2 + i] - sum(x[2 + i] for x in rows) / len(rows)) ** 2 for r in rows) / len(rows)) ** 0.5))
        await b.close()
asyncio.run(main())

