def script_text(sid):
    m = re.search(r'<script id="%s">(.*?)</script>' % sid, html, re.S)
    return m.group(1)

strategy = script_text('rampart-strategy')
sim = script_text('rampart-sim')
print('strategy chars', len(strategy), 'sim chars', len(sim))
# top-level declarations check
for name, src in (('strategy', strategy), ('sim', sim)):
    tops = re.findall(r'^(function|var|let|const|class)\s+([A-Za-z_$][\w$]*)', src, re.M)
    print(name, 'top-level declarations:', tops)

JS = """
([strategySrc, simSrc, seeds]) => {
  // forbidden globals are shadowed so any access from the strategy throws
  const boom = (n) => new Proxy({}, { get() { throw new Error('forbidden access: ' + n); } });
  const M = Object.create(Math); Object.defineProperty(M, 'random', { get() { throw new Error('forbidden access: Math.random'); } });
  const mk = new Function('window', 'document', 'THREE', 'performance', 'Date', 'Math', 'globalThis', 'self', strategySrc + '; return createStrategy;');
  const createStrategy = mk(boom('window'), boom('document'), boom('THREE'), boom('performance'), boom('Date'), M, boom('globalThis'), boom('self'));
  const sim = new Function(simSrc + '; return rampartSimulate;')();
  const out = [];
  const t0 = Date.now();
  for (const seed of seeds) {
    const t1 = Date.now();
    const r = sim(createStrategy, seed, 12020);
    out.push([seed, r.score, r.fallTick, r.log.length, r.hash, Date.now() - t1]);
  }
  // two independent strategy objects must not share state
  const a = createStrategy(), b = createStrategy();
  return { out, shared: a === b };
}
"""

