    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True)
        pg = await b.new_page()
        r = await pg.evaluate(JS, [strategy, sim, [42, 7, 100, 214]])
        for row in r['out']: print(row)
        print('objects distinct:', not r['shared'])
        await b.close()
asyncio.run(main())

