import asyncio, sys, json, os, base64
from playwright.async_api import async_playwright
THREE = '/private/tmp/pcd-sbx-claude-sonnet-5.5-xhigh-r2-7ggu4dcc/tmp/three-dl/three.min.js'
HTML = 'file:///private/tmp/pcd-sbx-claude-sonnet-5.5-xhigh-r2-7ggu4dcc/work/index.html'
SET = """(t) => { const s = document.getElementById('scrubber'); s.value = t; s.dispatchEvent(new Event('input', {bubbles: true})); }"""

DIFF = """async ([a, b]) => {
  const load = (s) => new Promise(r => { const i = new Image(); i.onload = () => r(i); i.src = 'data:image/png;base64,' + s; });
  const [ia, ib] = await Promise.all([load(a), load(b)]);
  const mk = (i) => { const c = document.createElement('canvas'); c.width = i.width; c.height = i.height; const g = c.getContext('2d'); g.drawImage(i, 0, 0); return g.getImageData(0, 0, i.width, i.height); };
  const A = mk(ia), B = mk(ib);
  let n = 0, x0 = 1e9, y0 = 1e9, x1 = -1, y1 = -1, maxd = 0;
  for (let y = 0; y < A.height; y++) for (let x = 0; x < A.width; x++) {
    const i = (y * A.width + x) * 4;
    const d = Math.abs(A.data[i] - B.data[i]) + Math.abs(A.data[i + 1] - B.data[i + 1]) + Math.abs(A.data[i + 2] - B.data[i + 2]);
    if (d > 0) { n++; x0 = Math.min(x0, x); y0 = Math.min(y0, y); x1 = Math.max(x1, x); y1 = Math.max(y1, y); maxd = Math.max(maxd, d); }
  }
  return { n, x0, y0, x1, y1, maxd, w: A.width, h: A.height };
}"""

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(headless=True, args=['--ignore-gpu-blocklist', '--use-angle=metal'])
        pg = await b.new_page(viewport={'width': 1280, 'height': 650})
        async def route(r): await r.fulfill(path=THREE, content_type='application/javascript')
        await pg.route('**/three.min.js', route)
        await pg.goto(HTML)
        await pg.wait_for_timeout(2500)
        await pg.click('#btn-toggle')
        shots = []
        seq = [12.34, 12.34, 3.0, 12.34, 55.5, 12.34]
        for t in seq:
            await pg.evaluate(SET, t)
            await pg.wait_for_timeout(500)
            shots.append(base64.b64encode(await pg.screenshot()).decode())
        cmp = await b.new_page()
        for i in range(1, len(seq)):
            if seq[i] == seq[0]:
                print('vs first #%d' % i, await cmp.evaluate(DIFF, [shots[0], shots[i]]))
        print('second vs fourth', await cmp.evaluate(DIFF, [shots[1], shots[3]]))
        await b.close()
asyncio.run(main())

