      m.rotation.y = Math.atan2(-dz, dx);
      m.position.set((pts[i][0] + pts[i + 1][0]) / 2, 0.05, (pts[i][1] + pts[i + 1][1]) / 2);
      m.renderOrder = 2;
      scene.add(m);
    }
  }

  // ---------------- build pads (instanced)
  {
    const g = mergeParts([
      CY(0.43, 0.5, 0.1, 10, 0x6d6e78, 0, 0.05, 0),
      CY(0.36, 0.36, 0.03, 10, 0x4a4b56, 0, 0.11, 0),
      BX(0.12, 0.08, 0.12, 0x85838c, 0.4, 0.1, 0, 0, 0.5, 0),
      BX(0.12, 0.08, 0.12, 0x85838c, -0.4, 0.1, 0, 0, 0.5, 0),
      BX(0.12, 0.08, 0.12, 0x85838c, 0, 0.1, 0.4, 0, 0.5, 0),
      BX(0.12, 0.08, 0.12, 0x85838c, 0, 0.1, -0.4, 0, 0.5, 0)
    ]);
    const pads = new THREE.InstancedMesh(g, litMat(), 16);
    pads.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(16 * 3).fill(1), 3);
    for (let s = 0; s < 16; s++) { _m4.makeTranslation(SLOT_TILES[s][0] + 0.5, 0, SLOT_TILES[s][1] + 0.5); pads.setMatrixAt(s, _m4); }
    pads.castShadow = true; pads.receiveShadow = true; pads.frustumCulled = false;
    scene.add(pads);
  }

  // ---------------- decor: rocks, pines, gate pillars (seeded)
  {
    const R = visRng(1234);
    const near = function (x, z, minPad, minRoad) {
      for (let s = 0; s < 16; s++) if (Math.hypot(x - SLOT_TILES[s][0] - 0.5, z - SLOT_TILES[s][1] - 0.5) < minPad) return true;
      const gr = ROUTES[0];
      for (let p = 0; p <= gr.len; p += 25) if (Math.hypot(x - gr.xs[p] / 100, z - gr.ys[p] / 100) < minRoad) return true;
      const ar = ROUTES[1];
      for (let p = 0; p <= ar.len; p += 25) if (Math.hypot(x - ar.xs[p] / 100, z - ar.ys[p] / 100) < 0.5) return true;
      if (Math.hypot(x - KEEP.x, z - KEEP.z) < 1.9) return true;
      return false;
    };
    const rockParts = [], treeParts = [];
    let placed = 0, guard = 0;
    while (placed < 150 && guard++ < 4000) {
      const x = -6 + R() * 36, z = -5 + R() * 26;
      const inBoard = x > 0 && x < 24 && z > 0 && z < 14;
      if (inBoard && R() < 0.55) continue;
      if (near(x, z, 0.9, 0.95)) continue;
      const dxo = Math.max(-x, x - 24, 0), dzo = Math.max(-z, z - 14, 0), mask = smooth01((Math.hypot(dxo, dzo) - 0.3) / 7);
      const y = mask * ((vnoise(x * 0.18, z * 0.18, 3) * 2.4 + vnoise(x * 0.45, z * 0.45, 5) + vnoise(x * 1.1, z * 1.1, 8) * 0.25) - 0.2);
      const lum = 0.7 + R() * 0.5, c = ((0x55 * lum) | 0) << 16 | ((0x55 * lum) | 0) << 8 | ((0x60 * lum) | 0);
      if (R() < 0.62) {
        const s = 0.12 + R() * 0.28;
        rockParts.push(part(new THREE.DodecahedronGeometry(1, 0), c, x, y + s * 0.4, z, R() * 3, R() * 6, R() * 3, s, s * (0.6 + R() * 0.4), s));
      } else {
        const s = 0.6 + R() * 0.7, tx = x, tz = z;
        treeParts.push(CY(0.05 * s, 0.08 * s, 0.4 * s, 5, 0x4a3426, tx, y + 0.2 * s, tz));
        treeParts.push(CY(0.0, 0.34 * s, 0.7 * s, 7, 0x1d3a2a, tx, y + 0.65 * s, tz));
        treeParts.push(CY(0.0, 0.26 * s, 0.6 * s, 7, 0x24472f, tx, y + 1.05 * s, tz));
      }
      placed++;
    }
    const rocks = new THREE.Mesh(mergeParts(rockParts), matLit);
    rocks.castShadow = true; rocks.receiveShadow = true; scene.add(rocks);
    const trees = new THREE.Mesh(mergeParts(treeParts), matLit);
    trees.castShadow = true; trees.receiveShadow = true; scene.add(trees);
    // gate pillars at the ground spawn and air spawn
    const gate = mergeParts([
      BX(0.4, 1.5, 0.4, 0x5b5963, 0.35, 0.75, 1.55), BX(0.4, 1.5, 0.4, 0x5b5963, 0.35, 0.75, 3.45),
      BX(0.5, 0.25, 2.3, 0x4c4a54, 0.35, 1.55, 2.5), BX(0.3, 0.12, 0.3, 0x7c2a2a, 0.35, 1.8, 1.55), BX(0.3, 0.12, 0.3, 0x7c2a2a, 0.35, 1.8, 3.45),
      BX(0.3, 1.1, 0.3, 0x4c4a54, 0.3, 0.55, 5.9), BX(0.3, 1.1, 0.3, 0x4c4a54, 0.3, 0.55, 7.1), BX(0.4, 0.16, 1.5, 0x3d6a78, 0.3, 1.18, 6.5)
    ]);
    const gm = new THREE.Mesh(gate, matLit); gm.castShadow = true; gm.receiveShadow = true; scene.add(gm);
  }

  // ---------------- the keep (walled, with 16 knock-off chunks)
  {
    const kg = new THREE.Group(); kg.position.set(KEEP.x, 0, KEEP.z); scene.add(kg);
    const matKeep = patchDesat(new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.85, metalness: 0.1, flatShading: true, emissive: 0xff1a1a, emissiveIntensity: 0 }));
    W.matKeep = matKeep; W.keep = kg;
    const base = new THREE.Mesh(mergeParts([BX(1.95, 0.1, 1.95, 0x4d4a55, 0, 0.05, 0), BX(1.7, 0.05, 1.7, 0x5f5b66, 0, 0.12, 0)]), matKeep);
    base.receiveShadow = true; kg.add(base);
    // chunk transforms (ring of 16 wall blocks)
    const chunks = [], R = visRng(99);
    for (let side = 0; side < 4; side++) for (let j = 0; j < 4; j++) {
      const s = -0.525 + j * 0.35, h = 0.72;
      let x, z, ry;
      if (side === 0) { x = s; z = -h; ry = 0; } else if (side === 1) { x = s; z = h; ry = 0; } else if (side === 2) { x = -h; z = s; ry = Math.PI / 2; } else { x = h; z = s; ry = Math.PI / 2; }
      chunks.push({ x: x, z: z, ry: ry, gate: side === 2 && (j === 1 || j === 2) });
    }
    // shuffled removal order (seeded)
    const order = chunks.map(function (c, i) { return i; });
    for (let i = order.length - 1; i > 0; i--) { const j = Math.floor(R() * (i + 1)); const t = order[i]; order[i] = order[j]; order[j] = t; }
    W.chunks = chunks; W.chunkOrder = order;
    W.chunkVel = chunks.map(function () { return [R() * 2 - 1, 2.5 + R() * 2.5, R() * 2 - 1, R() * 6 - 3, R() * 6 - 3]; });
    const cg = new THREE.BoxGeometry(0.34, 0.46, 0.2);
    const matKeepI = patchDesat(new THREE.MeshStandardMaterial({ roughness: 0.85, metalness: 0.1, flatShading: true, emissive: 0xff1a1a, emissiveIntensity: 0 }));
    W.matKeepI = matKeepI;
    const cm = new THREE.InstancedMesh(cg, matKeepI, 16);
    cm.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    cm.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(16 * 3), 3);
    for (let i = 0; i < 16; i++) {
      const c = chunks[i].gate ? lin(0x3c2c28) : lin(i % 3 === 0 ? 0x77737e : 0x69666f);
      cm.instanceColor.setXYZ(i, c.r, c.g, c.b);
    }
    cm.castShadow = true; cm.receiveShadow = true; cm.frustumCulled = false;
    kg.add(cm); W.chunkMesh = cm;
    // central tower + corner towers
    const tower = new THREE.Group(); kg.add(tower);
    const tm = new THREE.Mesh(mergeParts([
      BX(0.74, 0.8, 0.74, 0x6d6a76, 0, 0.5, 0), BX(0.84, 0.1, 0.84, 0x55525e, 0, 0.95, 0),
      CY(0.0, 0.62, 0.55, 4, 0x8a3a30, 0, 1.28, 0, 0, Math.PI / 4, 0),
      BX(0.04, 0.5, 0.04, 0x3c3a44, 0, 1.78, 0), BX(0.3, 0.18, 0.02, 0xc2392f, 0.16, 1.9, 0),
      BX(0.2, 0.26, 0.04, 0x2a1d1b, -0.0, 0.32, 0.38)
    ]), matKeep);
    tm.castShadow = true; tm.receiveShadow = true; tower.add(tm);
    W.tower = tower;
    const corners = new THREE.Group(); kg.add(corners); W.corners = corners;
    const cmesh = new THREE.Mesh(mergeParts([
      CY(0.18, 0.21, 0.85, 8, 0x75727d, 0.8, 0.5, 0.8), CY(0.0, 0.26, 0.3, 8, 0x8a3a30, 0.8, 1.08, 0.8),
      CY(0.18, 0.21, 0.85, 8, 0x75727d, -0.8, 0.5, 0.8), CY(0.0, 0.26, 0.3, 8, 0x8a3a30, -0.8, 1.08, 0.8),
      CY(0.18, 0.21, 0.85, 8, 0x75727d, 0.8, 0.5, -0.8), CY(0.0, 0.26, 0.3, 8, 0x8a3a30, 0.8, 1.08, -0.8),
      CY(0.18, 0.21, 0.85, 8, 0x75727d, -0.8, 0.5, -0.8), CY(0.0, 0.26, 0.3, 8, 0x8a3a30, -0.8, 1.08, -0.8)
    ]), matKeep);
    cmesh.castShadow = true; cmesh.receiveShadow = true; corners.add(cmesh);
    // warm lamp at the gate
    const lamp = new THREE.PointLight(0xff9a4a, 0.9, 5, 2); lamp.position.set(-1.0, 0.9, 0); kg.add(lamp);
  }

  buildActors();
  buildFx();
}

